-- =============================================================
-- 00122_seed_e_shikaku_b.sql
-- E資格（JDLA Deep Learning for ENGINEER） Set B / 42問 / 5カテゴリ
-- シラバス2026（2026年8月試験E2026#2より適用・第1.0版）準拠。Set Aと重複しない
-- テーマを中心に選定（SVD、二項分布、KLダイバージェンス、カーネル法、
-- Random Forest対勾配ブースティング、受容野、Attention内部、物体検出・生成モデルの
-- 発展形、距離学習・メタ学習・XAI、連合学習の分類など）。
-- calc(3段ロケット)とviz(SVG図解)は question-authoring-stats の流儀に従う。
-- 位置参照(A/B/C/D)は書かない。選択肢は長さ・密度を揃える。
-- 本番の再現ではなく学習用オリジナル。
-- =============================================================

BEGIN;

-- ── subject ──
INSERT INTO public.subjects (slug, name, description, color, sort_order)
VALUES ('e-shikaku-b', 'E資格（JDLA Deep Learning for ENGINEER） Set B',
        'JDLA E資格 対策 第2弾。シラバス2026（2026年8月試験E2026#2より適用）準拠。Set Aと重複しないテーマ（SVD・情報理論の発展、Random Forest対勾配ブースティング、受容野、Attention内部構造、物体検出・生成モデルの発展形、距離学習・メタ学習・XAI、連合学習の分類など）を中心に収録。本番の再現ではなく学習用オリジナル。',
        '#C2255C', 181)
ON CONFLICT (slug) DO NOTHING;

-- ── categories（Set Aと同じ公式シラバスの大分類5個） ──
INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, v.name, v.color, v.sort_order
FROM public.subjects s
CROSS JOIN (VALUES
  ('1. 数学的基礎', '#58a6ff', 0),
  ('2. 機械学習', '#3fb950', 1),
  ('3. 深層学習の基礎', '#a371f7', 2),
  ('4. 深層学習の応用', '#f0883e', 3),
  ('5. 開発・運用環境', '#39c5cf', 4)
) AS v(name, color, sort_order)
WHERE s.slug = 'e-shikaku-b'
ON CONFLICT (subject_id, name) DO NOTHING;

-- ── questions ──
INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('e-shikaku-b-q1', '1. 数学的基礎', '固有値分解と特異値分解(SVD)の違いとして正しいものはどれか。', NULL::text, '["固有値分解は正方行列にしか使えないのに対し、特異値分解は正方行列でない(行数と列数が違う)行列にも使える、より一般的な分解方法である。", "固有値分解は正方行列でない任意の形の行列にも使えるのに対し、特異値分解は正方行列にしか使えない、より限定的で応用範囲の狭い分解方法である。", "固有値分解と特異値分解はどちらも正方行列にしか使えず、適用できる行列の範囲に違いはない。", "固有値分解と特異値分解はどちらも同じ計算結果を返す、単なる呼び方だけが違う同一の手法である。"]', 0, '[0]', 'single', '{"asked": "固有値分解と特異値分解(SVD)の適用範囲の違い。", "why_asked": "PCAは対称行列(共分散行列)の固有値分解で説明されることが多いが、実装では正方行列でないデータ行列にそのままSVDを使う場合もあり、両者の使い分けを問われる。", "kid": "固有値分解は「正方形の表」専用、特異値分解は「縦横の数が違う表」でも使える広い版。", "terms": [["固有値分解", "正方行列Aを固有ベクトルと固有値を使ってA=PΛP⁻¹の形に分解する方法"], ["特異値分解(SVD)", "任意の(正方でなくてもよい)行列を、特異値と特異ベクトルを使ってA=UΣVᵀの形に分解する方法"]], "think": "固有値分解はAv=λvという関係を使うため、Aが正方行列でないと固有値・固有ベクトルの定義自体が成り立たない。特異値分解はAᵀAやAAᵀという必ず正方行列になる形を経由して計算するため、Aが正方でなくても定義できる。", "vs": "PCAで使われる共分散行列は必ず正方(かつ対称)なので固有値分解がそのまま使えるが、データ行列そのもの(サンプル数×特徴量数)は正方とは限らないため、直接SVDを使う流儀もある。", "opt": ["正解。固有値分解は正方行列限定、特異値分解は正方でない行列にも使える一般化された分解である。", "適用範囲の説明が入れ替わっている。正方行列でなくても使えるのは特異値分解であり、固有値分解は正方行列に限られる。", "特異値分解は正方でない行列にも使える点が固有値分解との決定的な違いであり、両者の適用範囲は同じではない。", "計算の仕組みも得られる分解の形(A=PΛP⁻¹かA=UΣVᵀか)も異なり、同一の手法の呼び方違いではない。"]}'),
  ('e-shikaku-b-q2', '1. 数学的基礎', 'あるコインを3回投げて表が出る回数Xは二項分布に従う。表が出る確率p=0.5のとき、ちょうど2回表が出る確率P(X=2)を二項分布の式 P(X=k)=nCk・p^k・(1-p)^(n-k) で求めるとどうなるか。', NULL::text, '["3/8。3回中2回表が出る組み合わせ数3通りに、それぞれの確率(0.5)³をかけて求める。", "1/8。2回連続で表が出る確率をそのまま答えにしてしまっている。", "1/2。表が出る確率pの値をそのまま答えにしてしまっている。", "2/3。表が出る回数2を試行回数3で割っただけの値を、そのまま確率として答えにしてしまっている。"]', 0, '[0]', 'single', '{"asked": "二項分布の式に具体的な数値を当てはめて、ちょうどk回成功する確率を計算する。", "why_asked": "ベルヌーイ試行の繰り返しである二項分布は、確率・統計の土台として、また性能評価の裏側にある考え方として頻出。", "kid": "コインを3回投げて「表2回・裏1回」になる組み合わせの数と、それぞれの起こりやすさをかけ算する。", "terms": [["ベルヌーイ試行", "結果が成功・失敗の2通りしかない1回の試行"], ["nCk(組み合わせ)", "n回のうちk回を選ぶ場合の数。ここでは「3回のうちどの2回が表か」を数える"]], "think": "3回中2回表になる「並び方」は表表裏・表裏表・裏表表の3通り(3C2=3)ある。それぞれの並びが起こる確率は(0.5)²×(0.5)¹=0.125で共通なので、3通り×0.125で合計の確率になる。", "calc": "n=3, k=2, p=0.5\n組み合わせの数 : 3C2 = 3通り(表表裏・表裏表・裏表表)\n1つの並びが起こる確率 : p²×(1-p)¹ = 0.5²×0.5 = 0.25×0.5 = 0.125\n全部足す(3通り分) : 3 × 0.125 = 0.375 = 3/8", "vs": "多項分布は「2種類より多い結果(サイコロの1〜6など)」を扱う、二項分布を一般化したもの。カテゴリカル分布は1回の試行だけを見た多項分布のさらに単純な版。", "opt": ["正解。3C2=3通りの並びそれぞれに確率0.125がかかり、合計3/8になる。", "1回の並び(例えば表表裏)が起こる確率(0.125=1/8)であり、3通りある並びを合計する手順が抜けている。", "1回の試行で表が出る確率pをそのまま3回中2回表という事象の確率として使ってしまっている。", "確率ではなく回数の割合(2÷3)を計算しており、二項分布の式そのものを使っていない。"]}'),
  ('e-shikaku-b-q3', '1. 数学的基礎', 'KLダイバージェンス D_KL(P||Q) = Σ P(x) log(P(x)/Q(x)) は2つの確率分布のズレを測る指標である。この指標の性質として正しいものはどれか。', NULL::text, '["D_KL(P||Q)とD_KL(Q||P)は一般に異なる値になる、非対称な指標である。", "D_KL(P||Q)とD_KL(Q||P)は常に同じ値になる、対称な指標である。", "KLダイバージェンスは常に負の値を取り、0に近いほど2つの分布が離れていることを表す。", "KLダイバージェンスは2つの分布が完全に一致していても、必ず正の値を取る。"]', 0, '[0]', 'single', '{"asked": "KLダイバージェンスが「距離」ではなく非対称な指標であるという性質。", "why_asked": "クロスエントロピー誤差はKLダイバージェンスと密接に関係する(クロスエントロピー=エントロピー+KLダイバージェンス)ため、この非対称性を理解しておくと損失関数の意味が繋がる。", "kid": "「PからQへのズレ」と「QからPへのズレ」は、測る向きが違うと答えも変わる、という性質。", "terms": [["JSダイバージェンス", "KLダイバージェンスを2方向平均するなどして対称にした指標"], ["クロスエントロピー", "H(P,Q)=H(P)+D_KL(P||Q) の関係でKLダイバージェンスと結びついている"]], "think": "D_KL(P||Q)はP(真の分布)を基準に「Qで近似したときの情報量のロス」を測る式で、P(x)を重みにしてlog(P(x)/Q(x))を足し合わせる。PとQを入れ替えると重みの掛かり方が変わるため、一般に同じ値にはならない。", "calc": "真の分布P=[0.9, 0.1]、近似分布Q=[0.5, 0.5]とする\nD_KL(P||Q) = 0.9×log(0.9/0.5) + 0.1×log(0.1/0.5)\n           = 0.9×log(1.8) + 0.1×log(0.2)\n           ≈ 0.9×0.59 + 0.1×(-1.61) ≈ 0.53 - 0.16 = 0.37\nD_KL(Q||P) = 0.5×log(0.5/0.9) + 0.5×log(0.5/0.1)\n           ≈ 0.5×(-0.59) + 0.5×1.61 ≈ -0.29 + 0.81 = 0.51\n→ 0.37 ≠ 0.51 で、向きによって値が変わる", "vs": "「距離」と呼ばれることもあるが、数学的な距離の公理(対称性)を満たさないため、厳密には距離ではない。", "opt": ["正解。P(x)を重みに使う式なので、PとQを入れ替えると一般に異なる値になる非対称な指標である。", "PとQを入れ替えても常に同じ値になる、という性質はKLダイバージェンスには成り立たない。", "KLダイバージェンスは0以上の値を取り、0に近いほど2つの分布が近いことを表す(逆の説明になっている)。", "2つの分布が完全に一致するとき、log(P(x)/Q(x))=log(1)=0になるため、KLダイバージェンスはちょうど0になる。"]}'),
  ('e-shikaku-b-q4', '1. 数学的基礎', '相互情報量I(X;Y)と条件付きエントロピーH(X|Y)は、どちらも2つの確率変数の関係を測る指標である。この2つの関係として正しいものはどれか。', NULL::text, '["相互情報量は「Yを知ることでXの不確実性がどれだけ減るか」を表し、I(X;Y)=H(X)-H(X|Y)という関係で条件付きエントロピーと結びついている。", "相互情報量は「Yを知ることでXの不確実性がどれだけ増えるか」を表し、I(X;Y)=H(X)+H(X|Y)という関係で条件付きエントロピーと結びついている。", "相互情報量と条件付きエントロピーは全く独立に定義されており、数式的なつながりは存在しない。", "相互情報量は常に0になり、XとYの関係の強さによって値が変わることはない。"]', 0, '[0]', 'single', '{"asked": "相互情報量と条件付きエントロピーの数式的な関係。", "why_asked": "情報理論の各指標(エントロピー・条件付きエントロピー・相互情報量)がバラバラの公式ではなく、1つの体系としてつながっていることを理解しているかを問う。", "kid": "相互情報量は「Yのことを知ったおかげで、Xについての『わからなさ』がどれだけ減ったか」を表す量。", "terms": [["条件付きエントロピーH(X|Y)", "Yの値が分かっている前提での、Xの残りの不確実性"], ["結合エントロピーH(X,Y)", "XとYを同時に見たときの、あわせた不確実性"]], "think": "H(X)はYを知る前のXの不確実性、H(X|Y)はYを知った後に残るXの不確実性。その差(減った分)が「Yを知ったことで得られた情報量」であり、これが相互情報量I(X;Y)の定義そのものになっている。", "vs": "XとYが完全に独立(無関係)なら、Yを知ってもXの不確実性は減らないためI(X;Y)=0になる。逆にYを知ればXが完全に分かるなら、H(X|Y)=0でI(X;Y)=H(X)になる。", "opt": ["正解。相互情報量はH(X)-H(X|Y)、つまりYを知ることで減ったXの不確実性の量として定義される。", "「減る」のではなく「増える」、また引き算ではなく足し算という説明になっており、実際の定義I(X;Y)=H(X)-H(X|Y)と食い違う。", "I(X;Y)=H(X)-H(X|Y)という数式的な関係で結びついており、独立に定義されているわけではない。", "相互情報量はXとYの関係が強いほど大きくなる量であり、常に0になるわけではない。"]}'),
  ('e-shikaku-b-q5', '1. 数学的基礎', 'ベクトルv=(3, 4)のL1ノルム(絶対値の和)とL2ノルム(2乗和の平方根)をそれぞれ求めるとどうなるか。', NULL::text, '["L1ノルムは7、L2ノルムは5。L1は各成分の絶対値をそのまま足し、L2は2乗して足してから平方根を取る。", "L1ノルムは5、L2ノルムは7。L1とL2の計算方法が入れ替わってしまっている。", "L1ノルムもL2ノルムも同じ12になる。どちらも各成分同士を単純に掛け合わせただけの値を使ってしまっている。", "L1ノルムは25、L2ノルムは25。2乗和をどちらのノルムにもそのまま使ってしまっている。"]', 0, '[0]', 'single', '{"asked": "ベクトルのL1ノルムとL2ノルムを、具体的な数値で計算する。", "why_asked": "L1正則化・L2正則化という名前の由来そのものであり、正則化の意味を数式レベルで理解する土台になる。", "kid": "L1ノルムは「まっすぐ足しただけの大きさ」、L2ノルムは「ふつうの意味での長さ(ユークリッド距離の考え方)」。", "terms": [["ノルム", "ベクトルの「大きさ」を測るものさし。L1・L2以外にもLpノルムという一般化がある"], ["Lpノルム", "各成分をp乗して足し、1/p乗するという形で一般化したノルム。p=1がL1、p=2がL2"]], "think": "L1ノルムは各成分の絶対値をただ足すだけ。L2ノルムはユークリッド距離の考え方そのもので、2乗して足してから平方根を取る。同じベクトルでも「測り方」が違えば値も変わる。", "calc": "v = (3, 4)\nL1ノルム : |3| + |4| = 3 + 4 = 7\nL2ノルム : √(3² + 4²) = √(9+16) = √25 = 5", "vs": "L1正則化(Lasso)は損失関数にL1ノルムを、L2正則化(Ridge)はL2ノルムをペナルティとして足す手法で、ノルムの定義の違いがそのまま正則化の効き方(疎になるかどうか)の違いに繋がる。", "opt": ["正解。L1ノルムは絶対値の和で7、L2ノルムは2乗和の平方根で5になる。", "L1ノルムとL2ノルムの計算方法(絶対値の和か、2乗和の平方根か)が入れ替わっている。", "各成分を掛け合わせる計算はL1ノルムにもL2ノルムにも当てはまらず、どちらも足し算をベースにした計算である。", "L2ノルムの計算途中の2乗和(25)を、平方根を取らずにそのまま両方のノルムとして使ってしまっている。"]}'),
  ('e-shikaku-b-q6', '1. 数学的基礎', '最尤推定では、複数のデータが独立に観測されたとする尤度(確率の掛け算)をそのまま最大化するのではなく、対数を取った対数尤度を最大化することが多い。この理由として正しいものはどれか。', NULL::text, '["対数を取ると掛け算が足し算に変わって計算・微分がしやすくなり、また確率の掛け算で値が極端に小さくなる(アンダーフローする)ことも防げるから。", "対数を取ると尤度の値が必ず大きくなり、より高い精度のモデルが得られることが保証されるから。", "対数を取ると足し算が掛け算に変わり、複数のデータをまとめて扱いやすくなるから。", "対数を取ると確率の値がちょうど0〜1の範囲からはみ出さなくなり、より正しい確率としてそのまま素直に解釈できるように、都合よく補正されてしまうから。"]', 0, '[0]', 'single', '{"asked": "なぜ尤度をそのまま最大化せず、対数尤度を最大化するのか。", "why_asked": "クロスエントロピー誤差など多くの損失関数に-log(確率)という形が登場する理由の背景にある考え方。", "kid": "確率をたくさん掛け算するとどんどん小さい数になって計算しづらくなるので、対数を使って「掛け算」を「足し算」に変えて扱いやすくする工夫。", "terms": [["対数尤度", "尤度(確率の積)にlogを取ったもの。積が和になり、微分の計算が扱いやすくなる"], ["アンダーフロー", "コンピュータが扱える最小の値より小さくなり、0として扱われてしまう問題"]], "think": "独立な複数データの尤度は確率の掛け算P(x1)×P(x2)×…になるが、確率(1未満の値)を何個も掛けると値がどんどん小さくなり、コンピュータの精度の限界で0になってしまうことがある。logを取るとlog(P(x1)×P(x2))=log P(x1)+log P(x2)のように掛け算が足し算に変わり、値も扱いやすい大きさに保たれる。", "vs": "logは単調増加関数なので、対数尤度を最大化するθと元の尤度を最大化するθは一致する。「対数を取っても最大化の答えは変わらない」という性質があるから、この置き換えが正当化される。", "opt": ["正解。掛け算が足し算になって微分しやすくなり、値が極端に小さくなる問題も防げるのが対数を取る理由である。", "対数を取ることでモデルの精度そのものが向上するわけではなく、あくまで計算上の扱いやすさのための工夫である。", "対数を取ると足し算ではなく、逆に掛け算が足し算に変わる(log(ab)=log a+log b)ため、説明の向きが逆になっている。", "対数を取った後の値は0〜1の範囲に収まらない(負の値になることも多い)ため、そのまま確率として解釈できるわけではない。"]}'),
  ('e-shikaku-b-q7', '2. 機械学習', '機械学習は教師あり学習・教師なし学習・半教師あり学習に分類されることがある。半教師あり学習の説明として正しいものはどれか。', NULL::text, '["ラベル付きデータとラベルなしデータの両方を使って学習する方式で、ラベル付けのコストが高い場面で有効。", "ラベル付きデータだけを使って学習する方式で、ラベルなしデータは一切使わない。", "ラベルなしデータだけを使って学習する方式で、ラベル付きデータは一切使わない。", "人間がその場でリアルタイムに正解を教え続けながら学習させる方式で、常に人手による付きっきりの介入を必要とする。"]', 0, '[0]', 'single', '{"asked": "半教師あり学習が、教師あり学習・教師なし学習とどう違うか。", "why_asked": "自己教師あり学習(Self-Training等)や能動学習のような発展的な学習方式の前提知識になる、機械学習の学習方式の全体地図。", "kid": "「答え付きの問題集」と「答えなしの問題集」を両方使って勉強する、いいとこ取りの方式。", "terms": [["教師あり学習", "入力とラベル(正解)のペアを使って学習する方式"], ["教師なし学習", "ラベルを使わず、データの構造そのものから何かを学び取る方式"]], "think": "現実にはラベル付けにコストがかかるため、少量のラベル付きデータと大量のラベルなしデータを組み合わせて学習効率を上げたい、というニーズから半教師あり学習が使われる。", "vs": "自己教師あり学習は、データ自体から擬似的な正解ラベルを自動生成して教師あり学習のように扱う、また別のアプローチ。", "opt": ["正解。半教師あり学習はラベル付き・ラベルなし両方のデータを組み合わせて使う学習方式である。", "これは教師あり学習の説明であり、ラベルなしデータも使う半教師あり学習の特徴を捉えていない。", "これは教師なし学習の説明であり、ラベル付きデータも使う半教師あり学習の特徴を捉えていない。", "半教師あり学習は「一部だけラベルがある」状態を扱う方式であり、常に人手のリアルタイム介入を必要とするわけではない。"]}'),
  ('e-shikaku-b-q8', '2. 機械学習', 'サポートベクターマシンのハードマージンとソフトマージンの違いとして正しいものはどれか。', NULL::text, '["ハードマージンは誤分類を一切許さずに境界線を引くのに対し、ソフトマージンは多少の誤分類やマージン内への侵入を許容して汎化性能を上げる。", "ハードマージンは誤分類を多少許容するのに対し、ソフトマージンは誤分類を一切許さない、より厳格でいっさいの妥協の余地も残さない設定である。", "ハードマージンとソフトマージンはどちらも誤分類を必ず一定数許容する点で共通しており、違いは存在しない。", "ハードマージンとソフトマージンは境界線の形状(直線か曲線か)の違いを表す用語である。"]', 0, '[0]', 'single', '{"asked": "SVMのハードマージンとソフトマージンという2つの設定の違い。", "why_asked": "現実のデータはきれいに分離できないことが多く、ソフトマージンという「多少の妥協」を許す設計判断がなぜ必要かを問う。", "kid": "ハードマージンは「1つも間違えてはいけない」という厳しいルール、ソフトマージンは「少しくらいのはみ出しは大目に見る」という柔らかいルール。", "terms": [["マージン", "境界線から最も近いデータ点までの余白の広さ"], ["カーネル法", "直線で分けられないデータを、高次元空間に写して分けやすくするテクニック"]], "think": "現実のデータには外れ値やノイズが混ざっていることが多く、ハードマージンのように「1つの誤分類も許さない」設定にすると、たった1つの外れ値のせいで境界線が大きく歪んだり、そもそも境界線が引けなくなったりする。ソフトマージンは多少のはみ出しにペナルティを課しつつ許容することで、より安定した境界線を引けるようにする。", "vs": "カーネル法は「境界線の形」を工夫して非線形な分離を可能にする技術で、マージンの厳しさ(ハード/ソフト)とは別の軸の話。", "opt": ["正解。ハードマージンは誤分類を許さない厳格な設定、ソフトマージンは多少の誤分類を許容する柔軟な設定である。", "厳格さの説明が入れ替わっている。誤分類を許さないのはハードマージン、多少許容するのはソフトマージンである。", "ハードマージンは本来「誤分類を一切許さない」設定であり、必ず一定数許容するという説明はソフトマージンにしか当てはまらない。", "境界線の形状(直線か曲線か)を決めるのはカーネル法の役割であり、ハードマージン・ソフトマージンは誤分類の許容度の話である。"]}'),
  ('e-shikaku-b-q9', '2. 機械学習', 'SVMで非線形なデータを分離するために使われる「カーネル法(カーネルトリック)」が行っていることの説明として正しいものはどれか。', NULL::text, '["データを高次元空間に写したときの内積の値を、実際にその高次元空間へ写す計算を省略しながら効率よく計算する。", "データを高次元空間に写す計算を、通常よりもさらに詳しく丁寧に、時間と手間をいくらでもかけて惜しまずに実行する方式である。", "データの次元を減らして、もとの低次元空間の中だけで境界線を探しやすくする。", "データを並べ替えるだけで、空間の次元自体は一切変えずに境界線を探す。"]', 0, '[0]', 'single', '{"asked": "カーネル法(カーネルトリック)が実際に何を計算で節約しているか。", "why_asked": "「高次元に写して分離する」という発想だけでなく、それを現実的な計算量で実現する仕組み(カーネルトリック)まで理解しているかを問う。", "kid": "本当に高次元の世界に引っ越さなくても、「引っ越した後の距離感」だけをうまく計算してしまう裏技。", "terms": [["カーネル関数", "高次元空間での内積を、元の低次元のデータだけから直接計算できる関数"], ["サポートベクター", "境界線に最も近く、マージンの大きさを決めているデータ点"]], "think": "低次元では直線で分けられないデータも、高次元に写すと直線(超平面)で分けられることがある。しかし実際に高次元の座標を計算するのは大変なので、カーネル関数を使って「高次元に写した後の内積」だけを元のデータから直接求めることで、高次元への変換自体を省略する。", "vs": "ハードマージン・ソフトマージンは「誤分類をどこまで許すか」という別の設定で、カーネル法(境界線の形をどう作るか)とは独立に組み合わせられる。", "opt": ["正解。カーネルトリックは高次元空間への変換を省略しつつ、その空間での内積の値だけを効率よく計算する技術である。", "カーネルトリックの狙いは計算を「省略して効率化する」ことであり、逆に詳しく丁寧に計算するという説明は目的と逆になっている。", "次元を減らすのはPCAなど次元圧縮の役割であり、カーネル法はむしろ高次元空間での分離を扱う技術である。", "カーネル法は空間の次元(の扱い方)そのものに関わる技術であり、単なるデータの並べ替えではない。"]}'),
  ('e-shikaku-b-q10', '2. 機械学習', 'Random Forestと勾配ブースティングは、どちらも複数の決定木を組み合わせるアンサンブル手法だが、木の作り方が異なる。この違いとして正しいものはどれか。', NULL::text, '["Random Forestは複数の決定木を並列に独立して学習させ多数決で決める(バギング)のに対し、勾配ブースティングは前の木の誤りを次の木が補正するように逐次的に学習させる(ブースティング)。", "Random Forestは前の木の誤りを次の木が補正するように逐次的に学習させる方式であり、勾配ブースティングは複数の決定木を並列に独立して学習させ最後にまとめて多数決を取るという方式である。", "Random Forestも勾配ブースティングも、どちらも1本の決定木だけを使い、複数の木を組み合わせることはない。", "Random Forestと勾配ブースティングは、決定木の分岐にGini係数を使うか使わないかだけが異なる、ほぼ同じ手法である。"]', 0, '[0]', 'single', '{"asked": "Random Forest(バギング)と勾配ブースティング(ブースティング)の、木を学習させる順序の違い。", "why_asked": "アンサンブル手法の2大潮流(並列に独立させるか、逐次的に補正するか)を区別できるかを問う頻出ポイント。", "kid": "Random Forestは「みんなで別々に考えて多数決」、勾配ブースティングは「前の人の間違いを次の人が直していくリレー」。", "terms": [["バギング", "複数のモデルを独立に(並列に)学習させ、多数決や平均で結果をまとめる方式"], ["ブースティング", "前のモデルの誤りに注目しながら、次のモデルを逐次的に追加していく方式"]], "think": "Random Forestは訓練データの一部をランダムに抽出(ブートストラップ)して複数の決定木を独立に育て、最後に多数決や平均を取る。勾配ブースティングは1本目の木の予測誤差(残差)を、2本目の木が埋めるように学習し、それを繰り返して木を1本ずつ追加していく。", "calc": "3本の決定木の多数決で考える(Random Forestのイメージ)\n木1の予測 : クラスA\n木2の予測 : クラスA\n木3の予測 : クラスB\n多数決 : A2票, B1票 → 最終的な予測はA\n(勾配ブースティングでは、この「独立な3票」ではなく、1本目の外し方を2本目が学習し直す、という逐次的な流れになる)", "vs": "Gini係数は1本1本の決定木がどこで分岐するかを決める基準であり、Random Forestか勾配ブースティングかという木の「組み合わせ方」の違いとは別のレイヤーの話。", "opt": ["正解。Random Forestは並列独立(バギング)、勾配ブースティングは逐次補正(ブースティング)という異なる組み合わせ方をする。", "並列に学習させるか逐次的に学習させるかの説明が入れ替わっている。並列(バギング)がRandom Forest、逐次(ブースティング)が勾配ブースティングである。", "どちらも複数の決定木を組み合わせるアンサンブル手法であり、1本だけの決定木を使うわけではない。", "木の作り方(並列か逐次か)がRandom Forestと勾配ブースティングの本質的な違いであり、Gini係数の使用有無だけの違いではない。"]}'),
  ('e-shikaku-b-q11', '2. 機械学習', '次元圧縮の手法であるt-SNEが抱える「Crowding Problem」と呼ばれる課題の説明として正しいものはどれか。', NULL::text, '["高次元空間ではそこそこ離れていた点同士が、低次元(2次元や3次元)に写すと窮屈になり、互いの距離を保ったまま配置しきれず、点同士が過度に密集してしまう問題。", "高次元空間の点の数が多すぎて、そもそも計算に時間がかかりすぎるという計算コストだけの問題。", "低次元に写した後、すべての点が完全に1本の一直線上にきれいに整列してしまい、クラスタ同士の区別がまったくつかなくなってしまうという、これもまた別種の困った問題。", "PCAと組み合わせて使うと、必ずエラーで計算が止まってしまうという実装上の不具合。"]', 0, '[0]', 'single', '{"asked": "t-SNEのCrowding Problemが、具体的にどんな現象を指しているか。", "why_asked": "t-SNEは可視化でよく使われる手法だが、この課題を知らずに結果の図をそのまま信じると誤読につながるため、限界を理解して使うことが重要。", "kid": "高次元の世界では余裕を持って離れていた点たちが、低次元という狭い空間に押し込められると、ぎゅうぎゅう詰めになってしまう問題。", "terms": [["主成分分析(PCA)", "データの分散が大きい方向を探して次元を減らす、線形な次元圧縮手法"], ["SNE", "t-SNEの元になった、確率分布の近さを保つように次元を圧縮する手法"]], "think": "高次元空間では「そこそこ近い」「そこそこ遠い」というバリエーションを表現する余地が広いが、2次元や3次元に押し込めると、その余地が足りなくなり、本来もう少し離れているべき点同士まで近くに集まってしまう。t-SNEはこの問題を緩和する工夫(t分布を使うなど)を取り入れた手法として設計されている。", "vs": "主成分分析(PCA)は線形な変換で次元を落とすため計算は軽いが、非線形な構造をうまく表現できないことがある。t-SNEは非線形な構造の可視化に強い代わりに、Crowding Problemのような別の課題を抱える。", "opt": ["正解。高次元での距離関係を低次元にそのまま再現しきれず、点同士が密集してしまう現象がCrowding Problemである。", "この課題は点同士の距離関係がうまく保てないという幾何学的な問題であり、単なる計算時間の長さの問題ではない。", "Crowding Problemは点が一直線に並ぶ現象を指す言葉ではなく、点が過度に密集してしまう現象を指す言葉である。", "PCAと組み合わせて使うこと自体は一般的な前処理として行われ、必ずエラーになるといった実装上の不具合の話ではない。"]}'),
  ('e-shikaku-b-q12', '2. 機械学習', '機械学習における「次元の呪い」と呼ばれる現象の説明として正しいものはどれか。', NULL::text, '["特徴量の次元数が増えるほど、同じ量のデータではデータ空間の中がスカスカ(疎)になり、距離に基づく手法の性能が悪化しやすくなる現象。", "特徴量の次元数が増えるほど、必ずモデルの学習速度が速くなり、全体の計算コストもどんどん下がり続けていくという都合の良い現象を指す。", "特徴量の次元数を減らすと、常にモデルの精度が上がり、過学習も同時に解消される現象。", "特徴量の次元数とは無関係に、データの件数だけによって発生するデータ不足の現象。"]', 0, '[0]', 'single', '{"asked": "「次元の呪い」が具体的にどんな問題を引き起こす現象か。", "why_asked": "k近傍法のような距離ベースの手法や、PCA・特徴量選択がなぜ重要なのかという理由の背景にある考え方。", "kid": "特徴量(見る項目)を増やせば増やすほど、同じ人数のデータでは「まわりに誰もいない」スカスカな空間になってしまう問題。", "terms": [["距離計算", "ユークリッド距離やマンハッタン距離のように、点同士の近さを測るものさし"], ["特徴量選択", "次元の呪いを緩和するために、重要な特徴量だけを選んで次元数を減らす工夫"]], "think": "次元が1つ増えるたびに、同じ密度でデータを埋めるために必要なデータ量は指数関数的に増えていく。データ数が足りないまま次元だけ増やすと、点同士がまばらになり「近くにデータがある」ということ自体が起きにくくなるため、k近傍法のような距離ベースの手法の前提が崩れやすくなる。", "vs": "主成分分析(PCA)による次元圧縮や特徴量選択は、この次元の呪いを緩和するための代表的な対策として使われる。", "opt": ["正解。次元が増えるほどデータ空間がスカスカになり、距離に基づく手法の性能が落ちやすくなるのが次元の呪いである。", "次元数が増えると一般には計算量も増える方向に働き、学習速度が必ず速くなるという説明は現象と逆である。", "次元を減らせば必ず精度が上がるとは限らず、重要な情報を失えば逆に精度が落ちることもある。", "次元の呪いはデータの件数だけでなく、特徴量の次元数との組み合わせ(データ数に対して次元が多すぎること)で起きる現象である。"]}'),
  ('e-shikaku-b-q13', '2. 機械学習', 'モデルの性能を検証する方法であるホールドアウト法とk分割交差検証法の違いとして正しいものはどれか。', NULL::text, '["ホールドアウト法はデータを訓練用と検証用に1回だけ分割するのに対し、k分割交差検証法はデータをk個に分割し、検証用パートを入れ替えながらk回学習・評価を繰り返して平均を取る。", "ホールドアウト法はデータをk個に分割して複数回検証を繰り返す方式であり、k分割交差検証法はデータを1回だけサッと分割してそのまま手早く簡単に済ませてしまう軽めの検証方式である。", "ホールドアウト法もk分割交差検証法も、どちらもデータを分割せず全データで学習と検証の両方を行う。", "ホールドアウト法とk分割交差検証法は同じ手順を指す別名であり、実施回数に違いはない。"]', 0, '[0]', 'single', '{"asked": "ホールドアウト法とk分割交差検証法の、データの分割回数・使い方の違い。", "why_asked": "検証データの選び方によって評価結果がぶれやすいデータ量が少ない場面で、なぜk分割交差検証法が好まれるのかという実務判断の背景になる。", "kid": "ホールドアウト法は「1回だけ分けてテストする」、k分割交差検証法は「何回も分け方を変えてテストして平均を取る」。", "terms": [["訓練データ・検証データ・テストデータ", "モデルを学習させる用・調整する用・最終評価する用に役割分担したデータ"], ["汎化誤差", "訓練に使っていない新しいデータに対する誤差。モデルの本当の実力の目安"]], "think": "ホールドアウト法は手軽だが、たまたま検証用に選ばれたデータの偏りによって評価結果が大きくぶれることがある。k分割交差検証法はデータをk個のブロックに分け、毎回違うブロックを検証用にしてk回学習・評価を繰り返すことで、特定の分割の偏りに評価結果が左右されにくくなる。", "vs": "訓練データ・検証データ・テストデータという3分割の考え方(ハイパーパラメータ調整用と最終評価用を分ける)は、ホールドアウト法・k分割交差検証法のどちらとも組み合わせて使われる、また別の軸の話。", "opt": ["正解。ホールドアウト法は1回だけの分割、k分割交差検証法はk回分割を入れ替えて繰り返し評価する方法である。", "分割・繰り返しの回数の説明が入れ替わっている。1回だけ分割するのがホールドアウト法、k回繰り返すのがk分割交差検証法である。", "どちらの方法もデータを訓練用と検証用に分割する手順を含んでおり、分割せずに全データで学習・検証を行う手法ではない。", "実施回数(1回か、k回繰り返すか)が両者の本質的な違いであり、同じ手順の別名ではない。"]}'),
  ('e-shikaku-b-q14', '2. 機械学習', '2値分類モデルの評価に使われるROC曲線とAUCの説明として正しいものはどれか。', NULL::text, '["ROC曲線は分類の閾値を変えながら偽陽性率(横軸)と真陽性率(縦軸)の変化を描いた曲線で、AUCはその曲線の下の面積であり、1に近いほど良いモデルとされる。", "ROC曲線は分類の閾値を固定したまま、訓練データの件数を変えながら正解率の変化を描いた曲線である。", "AUCはROC曲線の下の面積ではなく、曲線の最も高い1点だけの高さを表す指標である。", "ROC曲線とAUCは回帰タスクの誤差(MSEなど)の大きさだけを可視化するための専用の指標であり、分類タスクの評価にはおよそ一切使われることがないとされる。"]', 0, '[0]', 'single', '{"asked": "ROC曲線とAUCが何を軸にして描かれ、何を表す指標か。", "why_asked": "適合率・再現率のように1つの閾値での評価に対し、ROC曲線・AUCは「閾値をいろいろ変えたときの総合的な性能」を見る指標として、両者の違いを問われる。", "kid": "「陽性と判定するボーダーライン」を厳しくしたり緩くしたりしながら、見逃し(偽陽性率)と発見(真陽性率)のバランスがどう変わるかを描いたグラフ。", "terms": [["真陽性率(TPR)", "実際に陽性のもののうち、正しく陽性と判定できた割合。再現率と同じ計算式"], ["偽陽性率(FPR)", "実際は陰性なのに、誤って陽性と判定してしまった割合"]], "think": "分類モデルは「この確率以上なら陽性とする」という閾値を持つことが多く、閾値を変えると真陽性率・偽陽性率のバランスも変わる。ROC曲線はこの閾値をいろいろ動かしたときの軌跡を描いたもので、曲線が左上(真陽性率が高く偽陽性率が低い)に張り付くほど良いモデル。AUCはこの曲線の下の面積を数値化したもので、完全にランダムな予測なら0.5、完璧な予測なら1になる。", "vs": "適合率・再現率・F値は「1つの閾値」を固定したときの評価指標であるのに対し、ROC曲線・AUCは「閾値を動かした全体」を評価する指標という違いがある。", "opt": ["正解。ROC曲線は偽陽性率と真陽性率の関係を閾値ごとに描いた曲線で、AUCはその下の面積を表す。", "閾値を変えながら評価するのがROC曲線の本来の描き方であり、訓練データの件数を変える手法ではない。", "AUCはROC曲線の下の面積全体を表す指標であり、曲線上の1点の高さだけを表すものではない。", "ROC曲線・AUCは分類タスクの評価に使われる指標であり、回帰タスクの誤差を可視化するものではない。"]}'),
  ('e-shikaku-b-q15', '3. 深層学習の基礎', '1枚の画像に「犬」「猫」「鳥」のように複数のクラスが同時に写りうるマルチラベル分類の出力層の設計として正しいものはどれか。', NULL::text, '["クラスの数だけシグモイド関数を並べ、各クラスについて独立に「写っているかどうか」の確率を出力する。", "ソフトマックス関数を1つだけ使い、全クラスの確率の合計がちょうど1になるように出力全体を調整する。", "出力層を1つのニューロンだけにし、そのままクラス番号の数値を直接出力させる。", "各クラスに対応する重みをすべて0に固定し、入力に関わらず常に同じ出力を返すようにする。"]', 0, '[0]', 'single', '{"asked": "複数のクラスが同時に正解になりうるマルチラベル分類における出力層の作り方。", "why_asked": "「どれか1つを選ぶ」多クラス分類と「複数選べる」マルチラベル分類は出力層の設計が根本的に異なり、混同すると実装ミスに直結する。", "kid": "「犬か猫か鳥か、1つだけ選んで」ではなく「犬？いる？猫？いる？鳥？いる？」と、クラスごとに別々に0か1かを判定する。", "terms": [["シグモイド関数", "出力を0〜1の確率に変換する関数。各クラスに独立に使うとマルチラベルに対応できる"], ["ソフトマックス関数", "全クラスの確率の合計が1になるよう調整する関数。1つだけ選ぶ多クラス分類向き"]], "think": "多クラス分類は「排他的にどれか1つ」を選ぶのでソフトマックス(合計1)が適する。マルチラベル分類は各クラスが独立に「写っている/写っていない」の2択なので、クラスごとに独立なシグモイド関数(バイナリクロスエントロピーの考え方)を並べるのが自然。", "vs": "順序回帰(星1〜5の評価のような、順序があるカテゴリを予測するタスク)は、多クラス分類ともマルチラベル分類とも異なる、順序関係を考慮した出力設計が必要になる。", "opt": ["正解。クラスごとに独立なシグモイド関数を使うことで、複数クラスが同時に正解になりうるマルチラベル分類に対応できる。", "全クラスの合計を1にするソフトマックスは「排他的にどれか1つ」を選ぶ多クラス分類向けで、複数同時に正解になりうるマルチラベル分類には合わない。", "出力を1つの数値にまとめてしまうと、複数のクラスが同時に「写っている」という情報を表現できなくなる。", "重みを0に固定すると、入力に関わらず常に同じ出力しか返せず、そもそも学習が成立しない。"]}'),
  ('e-shikaku-b-q16', '3. 深層学習の基礎', 'tanh(双曲線正接関数)とシグモイド関数はどちらもS字カーブの活性化関数だが、tanhがシグモイドと違う点として正しいものはどれか。', NULL::text, '["tanhの出力範囲は-1〜1で0を中心にしているのに対し、シグモイドの出力範囲は0〜1で0を中心にしていない。", "tanhの出力範囲は0〜1で、シグモイドの出力範囲は-1〜1であり、それぞれの範囲の説明が入れ替わってしまっている。", "tanhは勾配消失が全く起きない活性化関数であり、シグモイドだけが勾配消失を起こす。", "tanhとシグモイドは全く同じ数式であり、呼び方が違うだけで出力の範囲や形に違いはない。"]', 0, '[0]', 'single', '{"asked": "tanhとシグモイドの出力範囲の違い。", "why_asked": "「0を中心にしているかどうか」は、その後の層への入力の分布に影響し、学習の安定性に関わる実務上のポイント。", "kid": "シグモイドは0〜1(必ずプラス側)、tanhは-1〜1(プラスもマイナスも出る)という出力の範囲の違い。", "terms": [["ゼロ中心(zero-centered)", "出力の平均がだいたい0になるような性質。次の層の学習を安定させやすい"], ["勾配消失", "tanhもシグモイドと同様、両端で傾きがほぼ0になるため起こりうる現象"]], "think": "シグモイドは常に正の値(0〜1)しか出力しないため、次の層への入力が常にプラス寄りに偏りやすい。tanhは-1〜1で0を中心にした出力になるため、この偏りが起きにくく、学習が多少安定しやすいとされる。ただしtanhも両端では傾きがほぼ0になるため、勾配消失自体はシグモイドと同様に起こりうる。", "vs": "ReLUはtanh・シグモイドとは違い、正の領域で傾きが常に1のまま一定という点が、両端が平らになるS字カーブとの決定的な違い。", "opt": ["正解。tanhは-1〜1で0を中心、シグモイドは0〜1で0を中心にしていない、という出力範囲の違いがある。", "出力範囲の説明が入れ替わっている。-1〜1になるのはtanh、0〜1になるのはシグモイドである。", "tanhも両端(入力が大きい・小さい)では傾きがほぼ0になるため、勾配消失が全く起きないわけではない。", "tanhとシグモイドは数式も出力の範囲も異なる別の関数であり、単なる呼び方違いではない。"]}'),
  ('e-shikaku-b-q17', '3. 深層学習の基礎', 'モメンタム法を改良したNesterov Accelerated Gradient(NAG)の特徴として正しいものはどれか。', NULL::text, '["現在の位置ではなく、これまでの慣性で「少し先に進んだ位置」を仮定してそこでの勾配を計算し、その情報を使って更新する。", "過去の勾配の情報を一切使わず、常にその場その場の勾配だけを見て更新していく、モメンタムよりもさらに単純な手法である。", "学習率をパラメータごとに完全に固定し、学習の途中で一切変化させない手法である。", "ミニバッチを使わず、必ず全データを使って1回の更新ごとに勾配を計算する手法である。"]', 0, '[0]', 'single', '{"asked": "NAGがモメンタム法とどう違う「先読み」をしているか。", "why_asked": "Adamの前身となる最適化アルゴリズムの発展の中で、モメンタムをさらに改良する工夫の考え方を理解しているかを問う。", "kid": "「今いる場所」ではなく「この勢いで少し先に進んだ場所」で坂の傾きを確認してから、実際に進む方向を決める工夫。", "terms": [["Pathological Curvature", "谷が細長くねじれたような、勾配降下法が振動しやすい損失関数の形状"], ["モメンタム", "過去の勾配の移動平均を使って更新方向に慣性を持たせる工夫"]], "think": "通常のモメンタムは「現在地の勾配」を使って慣性の方向を更新するが、NAGは「これまでの勢いでこの先どのあたりに進むか」を先に仮定し、その仮の地点での勾配を使って更新方向を補正する。これにより、慣性が行き過ぎそうなときに早めにブレーキをかけられるようになる。", "vs": "RMSProp・Adamは「学習率をパラメータごとに自動調整する」という別の軸の工夫であり、NAGの「勾配を計算する場所を先読みする」という工夫とは狙いが異なる(組み合わせて使うこともできる)。", "opt": ["正解。NAGは慣性で進んだ先の仮の位置での勾配を使って更新方向を補正する「先読み」の工夫を持つ。", "NAGはモメンタム法の発展形であり、過去の勾配の情報(慣性)をむしろ積極的に活用する手法である。", "学習率の自動調整はRMSProp・Adamのような別のアルゴリズムの特徴であり、NAG自体の特徴の説明ではない。", "ミニバッチを使うかどうかは学習の基本的なアルゴリズム(SGD等)の設定であり、NAGという先読みの工夫とは別の話。"]}'),
  ('e-shikaku-b-q18', '3. 深層学習の基礎', '適応的な学習率を持つアルゴリズムのうち、AdaGradが抱える弱点と、それをRMSPropがどう改善したかの説明として正しいものはどれか。', NULL::text, '["AdaGradは過去の勾配の2乗を際限なく累積するため学習率が単調に小さくなりすぎて学習が止まりやすいが、RMSPropは移動平均を使うことで最近の勾配を重視し、この問題を緩和している。", "AdaGradは学習が進むにつれて学習率がどんどん大きくなりすぎる問題を持ち、RMSPropはこれを固定の学習率に戻すことで解決した。", "AdaGradとRMSPropはどちらも勾配の情報を全く使わず、ランダムに学習率を決めるアルゴリズムである。", "AdaGradの弱点はモメンタムを一切使わないことであり、RMSPropはこれをモメンタムの追加だけで解決した(これはむしろAdamへの発展のしかたについての別の説明にあたる内容である)。"]', 0, '[0]', 'single', '{"asked": "AdaGradの弱点(学習率の減衰しすぎ)と、RMSPropによる改善の仕方。", "why_asked": "AdaGrad→RMSProp→Adamという最適化アルゴリズムの改良の系譜を、「何が問題で、どう直したか」のレベルで理解しているかを問う。", "kid": "AdaGradは学習が進むほどブレーキがどんどん強くなって、そのうち止まってしまう。RMSPropは「最近のブレーキ具合」だけを見るようにして、止まりすぎないようにした。", "terms": [["AdaGrad", "過去の勾配の2乗を累積し、その大きさに応じて学習率をパラメータごとに調整する手法"], ["移動平均", "直近のデータを重視し、古いデータの影響を徐々に薄めていく平均の取り方"]], "think": "AdaGradは学習が進むほど過去の勾配の2乗の累積が単調に大きくなり続けるため、その累積で割る学習率がどんどん小さくなり、いずれ更新がほとんど進まなくなる。RMSPropは「累積」ではなく「移動平均」を使うことで、古い勾配の影響を徐々に薄れさせ、学習率が際限なく小さくなり続けるのを防ぐ。", "vs": "Adamはこのモメンタム(慣性)とRMSProp(パラメータごとの学習率調整)を組み合わせたアルゴリズムで、AdaGrad・RMSPropの発展形にあたる。", "opt": ["正解。AdaGradは学習率が単調に減衰しすぎる弱点を持ち、RMSPropは移動平均でこれを緩和している。", "AdaGradの弱点は学習率が大きくなりすぎることではなく、逆に小さくなりすぎて学習が止まることである。", "AdaGrad・RMSPropはどちらも過去の勾配の大きさの情報を使って学習率を調整するアルゴリズムであり、ランダムに決めるものではない。", "モメンタムの追加はAdamの特徴であり、RMSPropはモメンタムではなく移動平均による学習率調整でAdaGradの弱点を緩和した。"]}'),
  ('e-shikaku-b-q19', '3. 深層学習の基礎', '畳み込み演算をGPU上で効率よく計算するための実装テクニックであるim2col(image to column)が行っていることの説明として正しいものはどれか。', NULL::text, '["入力画像のうちカーネルが重なる部分を展開して並べ直し、畳み込み演算を行列同士の掛け算(行列積)として計算できる形に変換する。", "入力画像をすべて0の値で最初から丸ごと埋め尽くしてしまい、本来必要な畳み込み演算そのものを実質的に行わずに済ませてしまう処理である。", "入力画像をランダムにシャッフルして、位置の情報を完全に消し去ってしまう。", "入力画像を1ピクセルだけ残してすべて削除し、極端に軽量化してしまう。"]', 0, '[0]', 'single', '{"asked": "im2colという実装テクニックが、畳み込み演算をどんな形に変換しているか。", "why_asked": "畳み込み層が実際にはGPU上で高速な行列積として実行されている、という理論と実装の橋渡しになる知識。", "kid": "画像の「窓の中身」を1列ずつ並べ直して、畳み込みという特殊な計算を、GPUが得意な「表と表の掛け算」に化けさせる工夫。", "terms": [["行列積", "行と列の内積で計算される掛け算。GPUがまとめて高速に処理するのが得意な演算"], ["特徴マップ", "畳み込み層の出力。フィルタが検出した特徴の強さを空間的に並べたもの"]], "think": "畳み込み演算は本来、カーネルを画像上でずらしながら要素ごとの積の和を取る手続き的な計算だが、これをそのままGPUで実行すると効率が悪い。im2colは画像の各窓(カーネルが重なる範囲)を1つの列として展開し、複数の窓をまとめた行列を作ることで、畳み込み演算全体を1回の大きな行列積として計算できるようにする。", "vs": "プーリングは特徴マップを縮小する別の演算であり、im2colのような「畳み込みの計算方式そのものを変換する」実装テクニックとは目的が異なる。", "opt": ["正解。im2colはカーネルが重なる範囲を展開して並べ直し、畳み込み演算を行列積として計算できる形に変換する技術である。", "im2colは畳み込み演算を効率よく実行するための変換技術であり、畳み込み演算そのものを行わずに済ませる仕組みではない。", "im2colは画像の値をカーネルの窓ごとに規則的に並べ直す変換であり、ランダムにシャッフルして位置情報を壊す処理ではない。", "im2colはデータの並べ方を変換する技術であり、画像の情報量を極端に削減する軽量化の手法ではない。"]}'),
  ('e-shikaku-b-q20', '3. 深層学習の基礎', 'CNNのある層のユニット1つが、入力画像のどれだけの範囲の情報を「見て」いるかを表す概念を受容野(receptive field)と呼ぶ。3×3のカーネルを持つ畳み込み層を2層重ねたとき、2層目のユニット1つが見ている入力画像上の範囲(1辺のサイズ)はどうなるか(ストライド1・パディングなしとする)。', NULL::text, '["5×5。1層目で3×3、2層目でさらに両端に1マスずつ広がるため、3+(3-1)=5となる。", "3×3。層を重ねても受容野は最初のカーネルサイズのまま変わらない。", "6×6。カーネルサイズ3を単純に2層分だけ足し合わせただけの値を、そのまま使ってしまっている。", "9×9。カーネルサイズ3を2層分掛け合わせただけの値になっている。"]', 0, '[0]', 'single', '{"asked": "畳み込み層を重ねると、受容野のサイズがどう広がっていくか。", "why_asked": "「なぜCNNは層を重ねるほど広い範囲の特徴(物体全体の形など)を捉えられるようになるのか」という仕組みの根拠になる概念。", "kid": "1層目は「窓3マス分」しか見えないが、2層目はその「3マス分」が重なり合った、もう少し広い範囲を間接的に見ていることになる。", "terms": [["受容野(receptive field)", "あるユニットの出力に影響を与えている、入力画像上の範囲の広さ"], ["特徴マップ", "畳み込み層の出力。1つのマスは対応する受容野の情報を集約したもの"]], "think": "1層目のユニットは入力の3×3マスを直接見ている。2層目のユニットは1層目の特徴マップの3×3マスを見ているが、その1層目の3×3マスそれぞれがさらに入力の3×3マスを見ているため、2層目から見た入力範囲は端が(3-1)マスずつ広がり、3+(3-1)=5×5になる。", "calc": "1層目の受容野 : 3×3(カーネルサイズそのまま)\n2層目で広がる分 : カーネルサイズ-1 = 3-1 = 2\n2層目の受容野 : 3 + 2 = 5 → 5×5", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">層を重ねると受容野が広がる</text><g transform=\"translate(90,30)\"><rect x=\"0\" y=\"0\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"0\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"0\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"0\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"0\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"0\" y=\"20\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"20\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"20\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"20\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"20\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"0\" y=\"40\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"40\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"40\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"40\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"40\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"0\" y=\"60\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"60\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"60\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"60\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"60\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"0\" y=\"80\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"80\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"40\" y=\"80\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"60\" y=\"80\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"80\" y=\"80\" width=\"20\" height=\"20\" fill=\"none\" stroke=\"#2a2f3f\"/><rect x=\"20\" y=\"20\" width=\"60\" height=\"60\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"2\"/><rect x=\"0\" y=\"0\" width=\"100\" height=\"100\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/></g><text x=\"245\" y=\"70\" fill=\"#c9a04a\" font-size=\"9\">1層目 3×3</text><text x=\"245\" y=\"86\" fill=\"#3b82f6\" font-size=\"9\">2層目 5×5</text></svg>", "vs": "プーリング層もストライドと同様に受容野を広げる効果を持つため、CNN全体の受容野は畳み込み層の数だけでなく、プーリングやストライドの設定にも左右される。", "opt": ["正解。1層目の3×3に、2層目で両端1マスずつ(カーネルサイズ-1=2)広がり、5×5になる。", "層を重ねるたびに受容野は広がっていくため、2層重ねても最初のカーネルサイズのままということはない。", "単純な足し算(3+3=6)ではなく、両端が(カーネルサイズ-1)ずつ広がるという計算になるため、6×6にはならない。", "掛け算(3×3=9)ではなく、両端が(カーネルサイズ-1)ずつ広がるという足し算に近い関係になるため、9×9にはならない。"]}'),
  ('e-shikaku-b-q21', '3. 深層学習の基礎', '軽量なCNN(MobileNet系など)で使われるdepth-wise畳み込みとpoint-wise畳み込み(1x1畳み込み)を組み合わせる設計の狙いとして正しいものはどれか。', NULL::text, '["depth-wise畳み込みでチャネルごとに空間方向の特徴を抽出し、point-wise畳み込み(1x1)でチャネル間の情報を混ぜることで、通常の畳み込みに近い表現力をより少ない計算量で得る。", "depth-wise畳み込みでチャネル同士の情報を混ぜ合わせ、point-wise畳み込みで空間方向の特徴を抽出するという、通常の畳み込みとはちょうど役割が完全に逆になってしまった設計である。", "depth-wise畳み込みとpoint-wise畳み込みはどちらも同じ計算を行う演算であり、組み合わせても計算量に変化はない。", "depth-wise畳み込みとpoint-wise畳み込みを組み合わせると、通常の畳み込みよりも必ず計算量が増えてしまう設計である。"]', 0, '[0]', 'single', '{"asked": "depth-wise畳み込みとpoint-wise畳み込みを組み合わせる、計算量削減の狙い。", "why_asked": "エッジデバイス向けの軽量なモデル設計(モデルの軽量化の章とも関連)の具体例として、通常の畳み込みをどう分解して計算量を減らすかという考え方を問う。", "kid": "普通の畳み込みが「空間もチャネルも同時に」処理するのに対し、この組み合わせは「まず空間だけ」「次にチャネルだけ」と仕事を分担することで、全体の計算量を減らす工夫。", "terms": [["point-wise畳み込み(1x1畳み込み)", "カーネルサイズが1×1の畳み込み。空間方向は混ぜず、チャネル方向の情報だけを混ぜ合わせる"], ["グループ化畳み込み", "チャネルをいくつかのグループに分けてそれぞれ独立に畳み込む、depth-wise畳み込みをさらに一般化した方式"]], "think": "通常の畳み込みは、各出力チャネルを作るために全ての入力チャネル×カーネルの空間全体を一度に計算するため計算量が大きい。depth-wise畳み込みは各チャネルを独立に(チャネル同士を混ぜずに)空間方向だけ畳み込み、その後point-wise畳み込み(1x1)でチャネル間の情報を混ぜることで、2段階に分けて同じような表現力をより少ない計算量で実現する。", "vs": "グループ化畳み込みは、depth-wise畳み込み(チャネルを1つずつのグループにする極端な場合)をさらに一般化し、いくつかのチャネルをまとめたグループ単位で畳み込む方式。", "opt": ["正解。depth-wise畳み込みは空間方向、point-wise畳み込みはチャネル方向という役割分担で、計算量を抑えつつ表現力を保つ設計である。", "空間方向とチャネル方向を処理する役割が入れ替わっている。空間方向を担うのがdepth-wise、チャネル方向を担うのがpoint-wiseである。", "depth-wise畳み込み(チャネルごとの空間畳み込み)とpoint-wise畳み込み(1x1のチャネル混合)は異なる計算を行う別の演算である。", "この組み合わせは通常の畳み込みよりも計算量を削減することを目的とした設計であり、計算量が増えるわけではない。"]}'),
  ('e-shikaku-b-q22', '3. 深層学習の基礎', '通常のRNNが「過去から現在まで」の情報しか使えないのに対し、双方向RNN(Bidirectional RNN)が持つ特徴として正しいものはどれか。', NULL::text, '["系列を前から読むRNNと後ろから読むRNNの2つを同時に使い、各時刻でその両方の出力を組み合わせることで、前後両方の文脈を考慮できる。", "系列を前から読むRNNだけをそのまま2倍の速さで動かすことで、後ろの情報もあらかじめ先読みできるようにしただけの、いたって単純な仕組みである。", "双方向RNNは過去の情報を一切使わず、未来の情報だけを使って出力を決める仕組みである。", "双方向RNNはLSTMやGRUのような特別なゲート機構を必ず内蔵していなければ成立しない仕組みである。"]', 0, '[0]', 'single', '{"asked": "双方向RNNが「前後両方の文脈」をどうやって扱っているか。", "why_asked": "BERTの双方向性(MLMで前後の文脈を使う)の土台になっている考え方で、系列モデルが「未来の情報」まで使えるようにする仕組みを問う。", "kid": "文章を「頭から読む係」と「お尻から読む係」の2人に分担させて、両方の意見を合わせて判断する仕組み。", "terms": [["順伝播の計算", "通常のRNNが行う、過去から現在に向かって情報を伝える計算"], ["エンコーダ・デコーダ", "双方向RNNは、系列全体をまるごと読み込みたいエンコーダ側でよく使われる構成"]], "think": "通常のRNNは時刻tの出力を計算するとき、それより前(過去)の情報しか使えない。双方向RNNは、同じ系列に対して「前から後ろへ読むRNN」と「後ろから前へ読むRNN」を別々に走らせ、各時刻でその2つの隠れ状態を連結(または合成)することで、その時刻の前後両方の文脈を考慮した出力を作れるようにする。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">双方向RNN：前向きと後ろ向きを合成</text><rect x=\"60\" y=\"35\" width=\"40\" height=\"24\" fill=\"none\" stroke=\"#3b82f6\"/><rect x=\"150\" y=\"35\" width=\"40\" height=\"24\" fill=\"none\" stroke=\"#3b82f6\"/><rect x=\"240\" y=\"35\" width=\"40\" height=\"24\" fill=\"none\" stroke=\"#3b82f6\"/><line x1=\"100\" y1=\"47\" x2=\"150\" y2=\"47\" stroke=\"#3b82f6\" stroke-width=\"1.5\" marker-end=\"url(#fw)\"/><line x1=\"190\" y1=\"47\" x2=\"240\" y2=\"47\" stroke=\"#3b82f6\" stroke-width=\"1.5\" marker-end=\"url(#fw)\"/><text x=\"20\" y=\"51\" fill=\"#3b82f6\" font-size=\"9\">前向き→</text><rect x=\"60\" y=\"80\" width=\"40\" height=\"24\" fill=\"none\" stroke=\"#c9a04a\"/><rect x=\"150\" y=\"80\" width=\"40\" height=\"24\" fill=\"none\" stroke=\"#c9a04a\"/><rect x=\"240\" y=\"80\" width=\"40\" height=\"24\" fill=\"none\" stroke=\"#c9a04a\"/><line x1=\"240\" y1=\"92\" x2=\"190\" y2=\"92\" stroke=\"#c9a04a\" stroke-width=\"1.5\" marker-end=\"url(#bw)\"/><line x1=\"150\" y1=\"92\" x2=\"100\" y2=\"92\" stroke=\"#c9a04a\" stroke-width=\"1.5\" marker-end=\"url(#bw)\"/><text x=\"290\" y=\"96\" fill=\"#c9a04a\" font-size=\"9\">←後ろ向き</text><defs><marker id=\"fw\" markerWidth=\"7\" markerHeight=\"7\" refX=\"3.5\" refY=\"3.5\" orient=\"auto\"><path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"#3b82f6\"/></marker><marker id=\"bw\" markerWidth=\"7\" markerHeight=\"7\" refX=\"3.5\" refY=\"3.5\" orient=\"auto\"><path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"#c9a04a\"/></marker></defs><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">各時刻で2方向の出力を組み合わせる</text></svg>", "vs": "GPT-nのような自己回帰モデルは「次のトークンを予測する」というタスクの性質上、未来の情報を使うと答えを覗き見ることになってしまうため、双方向にはできず前方向だけの文脈を使う設計になっている。", "opt": ["正解。前向き・後ろ向き2つのRNNの出力を組み合わせることで、双方向RNNは前後両方の文脈を考慮できる。", "双方向RNNは「2つの向きのRNNを組み合わせる」仕組みであり、1つのRNNを単に高速化しただけの仕組みではない。", "双方向RNNも過去方向の情報(前から読むRNN)は使っており、未来の情報だけを使う仕組みではない。", "LSTM・GRUのゲート機構は勾配消失対策のための別の工夫であり、双方向にすること自体はゲート機構の有無に関わらず可能である。"]}'),
  ('e-shikaku-b-q23', '3. 深層学習の基礎', '機械翻訳などで使われるseq2seq(sequence-to-sequence)モデルの基本構成として正しいものはどれか。', NULL::text, '["入力系列全体を固定長のベクトルに圧縮するエンコーダと、そのベクトルを元に出力系列を1つずつ生成していくデコーダの2つのRNNを組み合わせた構成。", "入力系列と出力系列を1つの同じRNNだけで、エンコーダ・デコーダという役割の区別を一切設けないまま、そのまま一緒くたに処理してしまう構成である。", "入力系列をそのまま出力系列としてコピーするだけの、学習を必要としない構成。", "出力系列の長さが入力系列の長さと必ず完全に一致することを前提にした構成。"]', 0, '[0]', 'single', '{"asked": "seq2seqモデルのエンコーダ・デコーダという基本構成。", "why_asked": "Attention機構やTransformerのEncoder-Decoder構造の直接の前身であり、この基本形を理解しているとTransformerの構造も理解しやすくなる。", "kid": "入力の文章を一度「意味のかたまり」に圧縮するエンコーダと、そのかたまりから出力の文章を1語ずつ作っていくデコーダの、2つのパートに分かれた仕組み。", "terms": [["エンコーダ", "入力系列を読み込んで、その情報を固定長のベクトル(文脈ベクトル)にまとめる部分"], ["デコーダ", "エンコーダが作った文脈ベクトルをもとに、出力系列を1つずつ生成していく部分"]], "think": "入力系列(例えば日本語の文)と出力系列(英語の文)は長さが違うことが多い。seq2seqはまずエンコーダで入力系列全体を1つの固定長ベクトルに要約し、デコーダがそのベクトルを初期状態として、出力系列を先頭から1つずつ生成していく、という2段構えの構成を取る。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">seq2seq：エンコーダ→文脈ベクトル→デコーダ</text><rect x=\"20\" y=\"45\" width=\"34\" height=\"24\" fill=\"none\" stroke=\"#3b82f6\"/><rect x=\"58\" y=\"45\" width=\"34\" height=\"24\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"56\" y=\"82\" fill=\"#3b82f6\" font-size=\"9\">入力系列</text><line x1=\"92\" y1=\"57\" x2=\"140\" y2=\"57\" stroke=\"#60a5fa\" stroke-width=\"2\" marker-end=\"url(#e1)\"/><circle cx=\"165\" cy=\"57\" r=\"16\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"2\"/><text x=\"165\" y=\"61\" fill=\"#c9a04a\" font-size=\"8\" text-anchor=\"middle\">文脈</text><line x1=\"181\" y1=\"57\" x2=\"225\" y2=\"57\" stroke=\"#6ab08d\" stroke-width=\"2\" marker-end=\"url(#e2)\"/><rect x=\"228\" y=\"45\" width=\"34\" height=\"24\" fill=\"none\" stroke=\"#6ab08d\"/><rect x=\"266\" y=\"45\" width=\"34\" height=\"24\" fill=\"none\" stroke=\"#6ab08d\"/><text x=\"264\" y=\"82\" fill=\"#6ab08d\" font-size=\"9\">出力系列</text><defs><marker id=\"e1\" markerWidth=\"7\" markerHeight=\"7\" refX=\"3.5\" refY=\"3.5\" orient=\"auto\"><path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"#60a5fa\"/></marker><marker id=\"e2\" markerWidth=\"7\" markerHeight=\"7\" refX=\"3.5\" refY=\"3.5\" orient=\"auto\"><path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"#6ab08d\"/></marker></defs></svg>", "vs": "Attention機構は、seq2seqの「1つの固定長ベクトルに全部詰め込む」という制約(長い入力ほど情報が失われやすい)を緩和するために、デコーダが入力系列の各部分に直接注目できるようにする改良として導入された。", "opt": ["正解。入力を1つのベクトルにまとめるエンコーダと、そこから出力を生成するデコーダの2つで構成される。", "seq2seqはエンコーダとデコーダという役割の異なる2つのRNNを組み合わせる構成であり、区別のない1つのRNNだけの構成ではない。", "seq2seqは学習によって入力から出力への変換を獲得するモデルであり、単なるコピーだけを行う構成ではない。", "機械翻訳のように、入力と出力の系列の長さが異なる場合にも対応できるのがseq2seqの利点であり、長さが一致する前提の構成ではない。"]}'),
  ('e-shikaku-b-q24', '3. 深層学習の基礎', 'TransformerがRNNのような再帰構造を持たないにもかかわらず、単語の並び順を扱えるようにするために導入している仕組みはどれか。', NULL::text, '["Positional Encoding。各トークンの埋め込みベクトルに、その位置(何番目のトークンか)を表す情報を足し合わせる。", "Masked Attention。未来のトークンを見えないように隠すための仕組みで、位置の情報そのものを表すためのものではない。", "Layer Normalization。層の中の値の分布を整える正規化の仕組みで、位置の情報とは無関係である。", "ドロップアウト。学習時にニューロンをランダムに無効化する正則化の仕組みで、位置の情報とは無関係である。"]', 0, '[0]', 'single', '{"asked": "Transformerが単語の順序をどうやって表現しているか。", "why_asked": "RNNは構造上自然に順序を扱えるが、Self-Attention自体は「どのトークンがどこにあるか」を区別しない演算のため、別の仕組みで順序を補う必要がある、という設計上の工夫を問う。", "kid": "「何番目の単語か」という情報を、単語の意味を表すベクトルにこっそり足し算して混ぜ込んでおく仕組み。", "terms": [["埋め込み(embedding)", "単語やトークンを、意味を表す数値のベクトルに変換したもの"], ["Self-Attention", "トークン同士の関連度を計算する仕組み自体には、並び順の情報が含まれていない"]], "think": "Self-Attentionは全トークンのペアの関連度を一斉に計算する仕組みで、そのままでは「隣同士か」「離れているか」といった位置関係を区別できない。Positional Encodingは、各トークンの位置に応じた固有のパターン(sin・cosを使った波など)を埋め込みベクトルに足すことで、モデルが位置の情報も手がかりにできるようにする。", "vs": "RNNは1つ前の時刻の隠れ状態を次の時刻に渡していく構造そのものが暗黙的に順序を表現するが、Transformerは全トークンを並列に処理するためこの仕組みがなく、Positional Encodingで明示的に補う必要がある。", "opt": ["正解。Positional Encodingは位置の情報を埋め込みベクトルに足し合わせることで、順序をモデルに伝える仕組みである。", "Masked Attentionは未来のトークンを隠す仕組みであり、位置そのものを表現するPositional Encodingとは役割が異なる。", "Layer Normalizationは値の分布を整える正規化の仕組みであり、位置の情報を扱う仕組みではない。", "ドロップアウトは正則化の仕組みであり、位置の情報を扱う仕組みではない。"]}'),
  ('e-shikaku-b-q25', '3. 深層学習の基礎', 'TransformerのMulti-Head Attentionが、Attentionを1回だけ計算するのではなく複数のヘッドに分けて計算する狙いとして正しいものはどれか。', NULL::text, '["それぞれのヘッドが異なる観点(文法的な関係、意味的な関係など)からトークン同士の関連度を並列に学習できるようにし、表現力を高める。", "計算を複数のヘッドに分けることで、Attentionの計算そのものを丸ごと完全に省略できるようにしてしまう、かなり大胆な工夫である。", "複数のヘッドに分けると、必ず1つのヘッドだけを使う場合よりも計算量が少なくなる。", "ヘッドを複数に分けることで、系列の長さそのものを短く圧縮する効果がある。"]', 0, '[0]', 'single', '{"asked": "Multi-Head Attentionが「複数のヘッドに分ける」ことで得られる利点。", "why_asked": "Self-Attentionを1回だけ計算するのではなく複数並列に行う理由を理解しているかを問う、Transformerの核心的な設計の1つ。", "kid": "1人だけで文章の関係を見るのではなく、複数人がそれぞれ違う視点(文法担当・意味担当など)で同時にチェックして、後で意見を合わせる仕組み。", "terms": [["Scaled Dot-Product Attention", "1つのヘッドの中で行われる、QとKの内積を使った基本のAttention計算"], ["ヘッド(head)", "Attentionを並列に計算する1つの「担当」の単位。それぞれ異なる部分空間に注目する"]], "think": "1回のAttention計算だけでは、トークン同士の関係のうち限られた種類の特徴しか捉えられないことがある。Multi-Head Attentionは、Q・K・Vをそれぞれ複数の小さな部分空間に分けて、独立に複数のAttentionを並列計算し、最後にそれらを結合することで、多様な観点からの関係性を同時に学習できるようにする。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">Multi-Head Attention：複数視点を並列に</text><rect x=\"20\" y=\"70\" width=\"30\" height=\"20\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"35\" y=\"105\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">入力</text><line x1=\"50\" y1=\"73\" x2=\"110\" y2=\"50\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><line x1=\"50\" y1=\"80\" x2=\"110\" y2=\"80\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><line x1=\"50\" y1=\"87\" x2=\"110\" y2=\"110\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><rect x=\"110\" y=\"40\" width=\"40\" height=\"20\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"130\" y=\"35\" fill=\"#3b82f6\" font-size=\"8\" text-anchor=\"middle\">head1</text><rect x=\"110\" y=\"72\" width=\"40\" height=\"20\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"165\" y=\"86\" fill=\"#c9a04a\" font-size=\"8\" text-anchor=\"middle\">head2</text><rect x=\"110\" y=\"100\" width=\"40\" height=\"20\" fill=\"none\" stroke=\"#6ab08d\"/><text x=\"130\" y=\"127\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">head3</text><line x1=\"150\" y1=\"50\" x2=\"220\" y2=\"78\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><line x1=\"150\" y1=\"80\" x2=\"220\" y2=\"80\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><line x1=\"150\" y1=\"110\" x2=\"220\" y2=\"82\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><rect x=\"222\" y=\"70\" width=\"60\" height=\"20\" fill=\"none\" stroke=\"#e8eaf0\"/><text x=\"252\" y=\"84\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">結合</text></svg>", "vs": "Scaled Dot-Product AttentionはMulti-Head Attentionの中で各ヘッドが行う基本計算そのものであり、Multi-Headはその計算を複数並列に走らせるための構成という関係にある。", "opt": ["正解。複数のヘッドがそれぞれ異なる観点から並列に関係性を学習することで、Attention全体の表現力を高めている。", "Multi-Head Attentionはヘッドを増やすことで表現力を高める工夫であり、Attentionの計算自体を省略する仕組みではない。", "ヘッドを複数に分けると、むしろそれぞれのヘッドの計算を合計するため、単純に1つのヘッドだけの場合より計算量は増える傾向にある。", "ヘッドの数は表現力に関わる設計であり、系列の長さ(トークンの数)そのものを短くする効果はない。"]}'),
  ('e-shikaku-b-q26', '3. 深層学習の基礎', 'ハイパーパラメータの最適化手法であるグリッドサーチとベイズ最適化の違いとして正しいものはどれか。', NULL::text, '["グリッドサーチは候補の組み合わせをあらかじめ格子状に決めて総当たりで試すのに対し、ベイズ最適化はこれまでの試行結果を踏まえて次に試す点を確率的に賢く選んでいく。", "グリッドサーチはこれまでの試行結果を踏まえて次の点を確率的に選び、ベイズ最適化は候補を格子状に決めて総当たりで試す。", "グリッドサーチとベイズ最適化はどちらも、ハイパーパラメータを一切変えずに固定したまま学習を行う方法である。", "グリッドサーチとベイズ最適化はどちらも、必ず同じ回数の試行でハイパーパラメータの最適値をぴったり見つけられることがすでに理論的に完全に保証されているとまで言われる。"]', 0, '[0]', 'single', '{"asked": "グリッドサーチ(総当たり)とベイズ最適化(賢い探索)の探し方の違い。", "why_asked": "ハイパーパラメータの組み合わせが多いとき、総当たりでは現実的な時間で終わらないことがあり、なぜベイズ最適化のような効率的な探索が使われるのかという実務判断につながる。", "kid": "グリッドサーチは「あり得る組み合わせを全部試す」総当たり方式、ベイズ最適化は「これまでの結果から次によさそうな組み合わせを予想して試す」賢い方式。", "terms": [["ランダムサーチ", "グリッドサーチのように格子状に決めず、候補をランダムに選んで試す方式。グリッドサーチより効率的なことがある"], ["基本的なハイパーパラメータ", "学習率・隠れ層の数・ユニット数・ドロップアウトの割合・バッチサイズなど、探索の対象になる設定値"]], "think": "グリッドサーチは各ハイパーパラメータについて候補値を決め、その全組み合わせを1つずつ試すため、パラメータの種類や候補が増えると試行回数が爆発的に増える。ベイズ最適化は、これまで試した組み合わせとその結果(性能)の関係から確率モデルを作り、「次に試すと良さそうな場所」を予測しながら効率よく探索を進める。", "vs": "ランダムサーチはグリッドサーチと同じく事前情報を使わない探索方法だが、格子状ではなくランダムに候補を選ぶ点が異なり、次元数が多い場合にグリッドサーチより効率的になることがある。", "opt": ["正解。グリッドサーチは総当たり、ベイズ最適化は過去の結果を踏まえた賢い探索という違いがある。", "探索の仕方の説明が入れ替わっている。総当たりで試すのがグリッドサーチ、賢く選ぶのがベイズ最適化である。", "グリッドサーチもベイズ最適化も、ハイパーパラメータをいろいろな値に変えながら試す探索手法であり、固定したまま学習する方法ではない。", "どちらの手法も探索の効率に違いがあり、必ず同じ回数で最適値が見つかることが保証されているわけではない。"]}'),
  ('e-shikaku-b-q27', '4. 深層学習の応用', '物体検出のFCOSが採用している「アンカーフリー(Anchor-Free)」という方式の説明として正しいものはどれか。', NULL::text, '["あらかじめ用意した多数の候補枠(Anchor box)を使わず、特徴マップ上の各点から直接その点が物体の中心にどれだけ近いかや、物体までの距離を予測する方式。", "あらかじめ用意した候補枠(Anchor box)の種類や数をさらに大幅に増やし、より多くの候補の中から時間をかけてじっくり選べるようにする、これもまた別の方式である。", "物体検出そのものを行わず、画像全体が1つのクラスに属するかどうかだけを判定する方式。", "候補領域の特徴マップを固定サイズに切り出すROI Poolingの、別の呼び方にすぎない方式。"]', 0, '[0]', 'single', '{"asked": "FCOSの「アンカーフリー」が、Faster R-CNNやYOLOのAnchor box方式とどう違うか。", "why_asked": "物体検出の設計思想は「候補枠を先に用意する(Anchor-based)」から「候補枠を使わず直接予測する(Anchor-Free)」へと発展しており、その転換点を理解しているかを問う。", "kid": "「あらかじめ用意した枠のテンプレート」に頼らず、画像の各点ごとに「ここは物体の中心にどれくらい近い？」と直接聞いていく方式。", "terms": [["Anchor box", "Faster R-CNNやYOLOなどが画像上にあらかじめ用意しておく、様々な大きさ・形の候補枠"], ["センターネス(Center-ness)", "FCOSで使われる、予測位置が物体の中心にどれだけ近いかを表すスコア"]], "think": "Faster R-CNNやYOLOはAnchor boxという「あらかじめ用意したテンプレートの枠」を基準に物体の位置を予測するが、Anchor boxの大きさ・形・数はハイパーパラメータとして調整が必要になる。FCOSはこのAnchor boxを使わず、特徴マップ上の各点(ピクセル)が直接「物体の中心からどれだけ離れているか」「境界までの距離」を予測する方式を取ることで、Anchor box設計の手間を省いている。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"90\" y=\"16\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">Anchor-based</text><rect x=\"45\" y=\"35\" width=\"90\" height=\"60\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/><rect x=\"60\" y=\"45\" width=\"60\" height=\"40\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/><text x=\"90\" y=\"110\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">候補枠を先に用意</text><text x=\"255\" y=\"16\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">Anchor-Free(FCOS)</text><circle cx=\"255\" cy=\"65\" r=\"3\" fill=\"#3b82f6\"/><line x1=\"255\" y1=\"65\" x2=\"255\" y2=\"40\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"255\" y1=\"65\" x2=\"290\" y2=\"65\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"255\" y1=\"65\" x2=\"255\" y2=\"90\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"255\" y1=\"65\" x2=\"220\" y2=\"65\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"255\" y=\"110\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">点から境界までの距離を直接予測</text></svg>", "vs": "Feature Pyramid Network(FPN)は複数の解像度の特徴マップを使ってさまざまな大きさの物体を検出しやすくする仕組みで、FCOSでも活用されるが、アンカーフリーという設計方針そのものとは別の要素。", "opt": ["正解。FCOSはAnchor boxを使わず、特徴マップ上の各点から直接、物体の中心までの近さや境界までの距離を予測する。", "アンカーフリーはAnchor boxを「使わない」方式であり、Anchor boxの種類を増やす方向の工夫ではない。", "FCOSは物体検出(位置とクラスの予測)を行う手法であり、画像全体の分類だけを行う手法ではない。", "ROI Poolingは候補領域の特徴を固定サイズに揃える別の処理であり、アンカーフリーという検出方式そのものの説明ではない。"]}'),
  ('e-shikaku-b-q28', '4. 深層学習の応用', '音声認識で使われるCTC(Connectionist Temporal Classification)が解決しようとしている課題として正しいものはどれか。', NULL::text, '["音声の各フレームと出力する文字列の対応(どのフレームがどの文字に当たるか)があらかじめ分からない状態でも、End-to-Endで学習できるようにする課題。", "音声データをあらかじめメルスペクトログラムに変換しておく地道な前処理そのものを、CTCが代わりにすべて自動で丸ごと肩代わりして行うようにするという課題である。", "複数の話者の声が混ざった音声から、特定の話者の声だけを分離するという課題。", "文字列を音声に変換する音声合成(Text-to-Speech)を実現するという課題。"]', 0, '[0]', 'single', '{"asked": "CTCが「音声のフレームと文字列の対応が分からない」という、音声認識特有の課題にどう対処しているか。", "why_asked": "音声(時間方向に細かく分割されたフレーム列)と、文字列(それより短い記号の列)の長さがそもそも違うという、系列変換タスク特有の難しさを理解しているかを問う。", "kid": "「あ」という音がどのフレームからどのフレームまでか、あらかじめ区切りを教えなくても、音声全体と文字列全体だけを見て学習できるようにする工夫。", "terms": [["ビームサーチ", "複数の候補の中から、最も確率が高そうな文字列を効率よく探す探索アルゴリズム"], ["End-to-Endモデル", "手作業で区切りやルールを作る中間処理を挟まず、入力から出力までを1つのモデルでまとめて学習する方式"]], "think": "音声を短いフレームに区切ると、フレーム数は文字数よりずっと多くなり、しかも「どのフレームがどの文字に対応するか」という区切りの正解ラベルは通常与えられていない。CTCは、同じ文字の連続や「空白(blank)」ラベルを許容しながら、あり得るすべてのフレーム↔文字の対応パターンを考慮した確率を計算することで、この区切りの情報なしにEnd-to-Endで学習できるようにする。", "vs": "WaveNetは音声「波形そのもの」を生成するモデル(音声合成)であり、CTCは音声から文字列を認識する(音声→テキスト)タスクを扱う点で、扱う向きが逆になる。", "opt": ["正解。CTCはフレームと文字の対応が未知のままでも、End-to-Endで音声認識を学習できるようにする手法である。", "メルスペクトログラムへの変換は別の前処理のステップであり、CTC自体はその後の系列変換の学習方法を扱う。", "話者分離は別のタスクであり、CTCはフレームと文字列の対応づけという別の課題を解決する手法である。", "音声合成(Text-to-Speech)はWaveNetのようなモデルが扱うタスクで、CTCは音声認識(音声→文字列)の学習方法である。"]}'),
  ('e-shikaku-b-q29', '4. 深層学習の応用', '音声波形を生成するWaveNetが使う「Dilated Causal Convolution」という畳み込みの工夫の説明として正しいものはどれか。', NULL::text, '["未来の時刻を見ないように過去方向だけを畳み込み対象にしつつ(Causal)、畳み込みのマス目の間隔を広げていく(Dilated)ことで、少ない層数でも広い範囲の過去の情報を参照できるようにする。", "未来の時刻の情報も惜しみなく積極的に先取りしてかなり自由に使いながら、畳み込みのマス目の間隔をどんどん狭めていくことで、直前のごく短い情報だけにひたすら集中して参照するようにするだけの仕組みである。", "すべての時刻の情報を平等に1つの値に平均してしまい、時系列の順序に関する情報を完全に無視する。", "畳み込みを一切行わず、全結合層だけで音声波形を1サンプルずつ生成する。"]', 0, '[0]', 'single', '{"asked": "WaveNetのDilated Causal Convolutionという畳み込みの工夫が何をしているか。", "why_asked": "音声波形は非常に長い系列(1秒で数万サンプル)になるため、RNNではなく畳み込みで長い範囲を効率よく参照する工夫として、CNNの応用範囲の広さを示す例。", "kid": "Causal(未来を見ない)は「先の展開をカンニングしない」というルール、Dilated(間隔を広げる)は「1マスずつではなく、飛び飛びに広い範囲を見る」工夫。", "terms": [["Causal Convolution", "出力の時刻より未来の入力を使わないように制約した畳み込み。生成タスクで「未来を覗き見ない」ために必要"], ["Dilated Convolution", "カーネルの各マスの間隔(間引き具合)を層ごとに広げていく畳み込み。層を重ねるだけで受容野が指数的に広がる"]], "think": "音声合成では「次のサンプルを生成するときに未来のサンプルを見てはいけない」ため、Causal(過去方向だけを見る)畳み込みが必要になる。さらに、長い音声波形の遠くの情報まで少ない層数で参照したいため、Dilated(間隔を空けて畳み込む)convolutionを使い、層を重ねるごとに参照できる範囲(受容野)を指数関数的に広げていく。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">Dilated Causal Convolution：層ごとに間隔を広げる</text><line x1=\"20\" y1=\"115\" x2=\"320\" y2=\"115\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><circle cx=\"30\" cy=\"115\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"70\" cy=\"115\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"110\" cy=\"115\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"150\" cy=\"115\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"190\" cy=\"115\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"230\" cy=\"115\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"270\" cy=\"115\" r=\"3\" fill=\"#8892a4\"/><circle cx=\"310\" cy=\"115\" r=\"3\" fill=\"#3b82f6\"/><path d=\"M270,115 Q290,90 310,115\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.2\"/><path d=\"M230,115 Q290,55 310,115\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.2\"/><path d=\"M150,115 Q230,25 310,115\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.2\"/><text x=\"325\" y=\"128\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"end\">出力(未来を見ない)</text></svg>", "vs": "Residual BlockやSkip Connectionは、WaveNetのような深いネットワークでも勾配が伝わりやすくするための工夫で、Dilated Causal Convolution(受容野を広げる工夫)とは目的が異なる。", "opt": ["正解。過去方向だけを見るCausalの制約と、間隔を広げて受容野を効率的に拡大するDilatedの工夫を組み合わせている。", "未来の情報を使わないのがCausalの本来の制約であり、未来を積極的に使うという説明は逆になっている。", "時系列の順序情報を活かして次のサンプルを予測することがWaveNetの目的であり、順序を無視して平均するわけではない。", "WaveNetは畳み込み(Dilated Causal Convolution)を積み重ねて構成されるモデルであり、畳み込みを使わない全結合層だけの構成ではない。"]}'),
  ('e-shikaku-b-q30', '4. 深層学習の応用', '生成モデルの一種である拡散モデル(Diffusion Model)の大まかな仕組みとして正しいものはどれか。', NULL::text, '["データに段階的にノイズを加えていく過程(拡散過程)を学習の材料にし、そのノイズを段階的に取り除く過程を学習することで、ノイズから新しいデータを生成できるようにする。", "データに一度も手を加えず、そのままの形を記憶しておき、必要なときにそっくりそのまま出力する。", "画像を周波数成分に分解し、その周波数成分の平均値だけを新しいデータとして出力する。", "2つのネットワーク(生成器と識別器)を互いに競わせることで学習する、GANとまったく同じ仕組みだけしか結局持たない、実質的にはほとんど単なる呼び方違いのモデルにすぎない。"]', 0, '[0]', 'single', '{"asked": "拡散モデルが「ノイズを足す・取り除く」という考え方でどうデータを生成しているか。", "why_asked": "2026シラバスで比重が増した生成モデル分野の中でも、GAN・VAEと並ぶ代表的なアプローチとして、その基本的な発想を問う。", "kid": "写真に少しずつ砂嵐(ノイズ)を足していってぐちゃぐちゃにする過程を学習し、その逆再生(ノイズを少しずつ取り除く)ができるようになれば、真っ白なノイズから新しい写真を作れるようになる、という発想。", "terms": [["識別モデルと生成モデル", "識別モデルはデータのクラスを見分ける、生成モデルは新しいデータそのものを作り出すという役割の違い"], ["自己回帰", "一部の生成モデルが使う、前の出力をもとに次を順番に生成していく方式"]], "think": "拡散モデルはまず、元のデータに少しずつノイズを加えていき最終的に完全なノイズにしてしまう「拡散過程」を考える。この過程の「逆」、つまりノイズから少しずつ元のデータらしきものを復元していく「逆拡散過程」をニューラルネットワークに学習させることで、学習後は真新しいノイズから出発して段階的にノイズ除去を繰り返し、新しいデータを生成できるようになる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">拡散過程とその逆(生成)</text><rect x=\"30\" y=\"45\" width=\"40\" height=\"40\" fill=\"#3b82f6\" opacity=\"0.9\"/><rect x=\"100\" y=\"45\" width=\"40\" height=\"40\" fill=\"#3b82f6\" opacity=\"0.6\"/><rect x=\"170\" y=\"45\" width=\"40\" height=\"40\" fill=\"#3b82f6\" opacity=\"0.35\"/><rect x=\"240\" y=\"45\" width=\"40\" height=\"40\" fill=\"#3b82f6\" opacity=\"0.15\"/><text x=\"50\" y=\"100\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">元データ</text><text x=\"260\" y=\"100\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">ノイズ</text><line x1=\"80\" y1=\"55\" x2=\"160\" y2=\"55\" stroke=\"#c47070\" stroke-width=\"1.5\" marker-end=\"url(#df)\"/><text x=\"120\" y=\"45\" fill=\"#c47070\" font-size=\"8\" text-anchor=\"middle\">拡散(ノイズ付加)</text><line x1=\"240\" y1=\"80\" x2=\"90\" y2=\"80\" stroke=\"#6ab08d\" stroke-width=\"1.5\" marker-end=\"url(#dg)\"/><text x=\"165\" y=\"112\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">逆拡散(ノイズ除去=生成)</text><defs><marker id=\"df\" markerWidth=\"7\" markerHeight=\"7\" refX=\"3.5\" refY=\"3.5\" orient=\"auto\"><path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"#c47070\"/></marker><marker id=\"dg\" markerWidth=\"7\" markerHeight=\"7\" refX=\"3.5\" refY=\"3.5\" orient=\"auto\"><path d=\"M0,0 L7,3.5 L0,7 z\" fill=\"#6ab08d\"/></marker></defs></svg>", "vs": "GANは生成器と識別器の対立構造で学習するのに対し、拡散モデルはノイズの付加・除去という1つのプロセスを段階的に学習する点で、仕組みが根本的に異なる。", "opt": ["正解。ノイズを加える過程を学習の材料にし、それを取り除く過程を学習することで新しいデータを生成する仕組みである。", "拡散モデルは学習によってノイズ除去の過程を獲得するモデルであり、データをそのまま記憶して出力する仕組みではない。", "拡散モデルはノイズの付加・除去という時間方向のプロセスを扱うモデルであり、周波数成分の平均を取る仕組みではない。", "生成器と識別器を競わせる仕組みはGAN特有のものであり、拡散モデルはノイズの付加・除去という別の仕組みで学習する。"]}'),
  ('e-shikaku-b-q31', '4. 深層学習の応用', '条件付きGAN(Conditional GAN)とCycleGANの違いとして正しいものはどれか。', NULL::text, '["条件付きGANはクラスラベルなどの条件を生成器・識別器の両方に与えて「指定した条件に合うデータ」を生成させるのに対し、CycleGANはペアになっていない2つのドメイン間で画像を相互に変換することを目指す。", "条件付きGANはペアになっていない2つのドメイン間で画像を相互に変換することを目指すのに対し、CycleGANはクラスラベルなどの条件をあらかじめ生成器・識別器の両方に与えて生成の仕方をきめ細かく制御する。", "条件付きGANとCycleGANはどちらも、識別器を一切使わずに生成器だけで学習する手法である。", "条件付きGANとCycleGANはどちらも、生成モデルではなく分類モデルの一種である。"]', 0, '[0]', 'single', '{"asked": "条件付きGANとCycleGANという、GANの2つの発展形の狙いの違い。", "why_asked": "基本的なGAN(モード崩壊などの課題)から、実用上「生成を制御したい」「対応データがなくても変換したい」というニーズにどう応えてきたかという発展の流れを問う。", "kid": "条件付きGANは「この数字の画像を作って」と注文を付けられるGAN、CycleGANは「馬の写真をシマウマ風に変換して」のように、ペアの正解データがなくても変換できるGAN。", "terms": [["モード崩壊", "生成器が識別器を騙しやすい一部のパターンに偏り、多様性が失われるGANの学習の課題"], ["ドメイン", "画像のスタイルや種類のまとまり(例えば「馬の写真」と「シマウマの写真」)を指す言葉"]], "think": "通常のGANはランダムなノイズから何が生成されるかを制御できないが、条件付きGANはクラスラベルなどの条件を追加入力として生成器・識別器の両方に与えることで、「指定した条件に沿ったデータ」を生成できるようにする。CycleGANは、ペア(対応関係)のある訓練データが用意しにくい状況(馬とシマウマの同じ構図の写真のペアなど)でも、2つのドメイン間を行き来する変換を学習できるように、行って戻ってくる一貫性(サイクル一貫性)を利用する。", "vs": "基本的なGANの生成器・識別器の対立構造は、条件付きGAN・CycleGANのどちらにも土台として使われており、その上に「条件を与える」「ペアなしで変換する」という追加の工夫が乗っている。", "opt": ["正解。条件付きGANは条件を与えて生成を制御し、CycleGANはペアなしのドメイン間変換を目指す、それぞれ異なる狙いを持つ。", "狙いの説明が入れ替わっている。ペアなしのドメイン変換を行うのはCycleGAN、条件を与えて制御するのは条件付きGANである。", "どちらのGANも識別器を使って生成器と競わせる学習を行っており、識別器を使わない仕組みではない。", "条件付きGAN・CycleGANはどちらも新しいデータを作り出す生成モデルであり、分類だけを行うモデルではない。"]}'),
  ('e-shikaku-b-q32', '4. 深層学習の応用', '深層強化学習のA3C(Asynchronous Advantage Actor-Critic)で使われる「Actor-Critic法」の考え方として正しいものはどれか。', NULL::text, '["行動を選ぶ役割(Actor、方策)と、その行動の良さを評価する役割(Critic、価値関数)を別々に学習させ、Criticの評価をもとにActorの方策を更新していく。", "行動を選ぶ役割と評価する役割を1つの同じネットワークに無理やりまとめてしまい、常に全く同じたった1つの出力だけをずっと律儀にそのまま両方の目的にひたすら使い回してしまう。", "行動を選ぶ役割だけを学習させ、その行動の価値を評価する仕組みは一切用意しない。", "評価する役割だけを学習させ、行動そのものを選ぶ仕組みは用意せず常にランダムに行動する。"]', 0, '[0]', 'single', '{"asked": "Actor-Critic法における「Actor」と「Critic」という2つの役割の関係。", "why_asked": "DQN(価値関数だけを学習する手法)とは異なるアプローチとして、方策そのものを直接学習する方策勾配法の考え方を理解しているかを問う。", "kid": "Actor(行動する係)が実際に動き、Critic(評価する係)が「その動き、良かったよ/イマイチだったよ」とアドバイスして、Actorがそれを参考に上達していく仕組み。", "terms": [["方策勾配法(Policy Gradient)", "行動を選ぶ確率(方策)そのものを、期待される報酬が大きくなる方向に直接更新していく手法"], ["行動価値関数Q", "DQNが学習する、ある状態で行動を取ったときの将来の報酬の期待値を表す関数"]], "think": "方策勾配法だけだと、行動の良さを測るために毎回多くの試行を平均する必要があり学習が不安定になりやすい。Actor-Criticは、Actor(方策)が行動を選び、Critic(価値関数)がその行動がどれだけ良かったかを素早く評価してActorにフィードバックすることで、方策勾配法の学習を安定させる。A3Cはこれを複数のエージェントで非同期(Asynchronous)に並列実行することで、さらに学習を効率化する手法。", "vs": "DQNは行動価値関数Q(価値)だけを学習し、行動はそのQ値が最大になるものを選ぶという間接的なアプローチだが、Actor-Criticは方策(Actor)を直接学習する点が異なる。", "opt": ["正解。行動を選ぶActorと、その評価を行うCriticを分担させ、Criticの評価をもとにActorを更新していく仕組みである。", "ActorとCriticは異なる役割(行動選択と価値評価)を担う別々の要素であり、1つの出力を使い回す仕組みではない。", "Critic(評価する仕組み)もActor-Criticの重要な構成要素であり、評価の仕組みを一切用意しないわけではない。", "Actor(行動を選ぶ仕組み)もActor-Criticの重要な構成要素であり、常にランダムに行動するわけではない。"]}'),
  ('e-shikaku-b-q33', '4. 深層学習の応用', '転移学習において、学習元のドメイン(データの分布)と学習先のドメインが異なることで性能が落ちてしまう問題を指す言葉として正しいものはどれか。', NULL::text, '["ドメインシフト。学習元と学習先でデータの分布が異なるために、学習元でうまくいったモデルがそのままでは学習先でうまく機能しなくなる現象。", "ファインチューニング。学習済みモデルの一部を、新しいタスク用のデータで追加学習して細かく調整していく具体的な手法そのものを指す言葉である。", "過学習。訓練データを丸暗記してしまい、新しいデータへの性能が落ちる現象を指す言葉。", "モード崩壊。GANの生成結果の多様性が失われてしまう現象を指す言葉。"]', 0, '[0]', 'single', '{"asked": "転移学習における「学習元と学習先のデータ分布のズレ」を指す専門用語。", "why_asked": "転移学習・ドメイン適応というテーマの中心にある問題設定そのものを言い当てられるかを問う。", "kid": "「昼間の写真だけで練習した見分け方」を「夜の写真」にそのまま使おうとすると、うまくいかなくなる、というズレの問題。", "terms": [["ドメイン適応(domain adaptation)", "ドメインシフトの影響を緩和し、学習先のドメインでもうまく機能するようにモデルを調整する技術"], ["ファインチューニング", "事前学習済みモデルを、新しいタスク・ドメインのデータで追加学習して調整する具体的な手法"]], "think": "転移学習は、大量データで学習済みのモデルを別のタスク・ドメインに流用する技術だが、元のドメイン(例えば昼間の画像)と新しいドメイン(例えば夜間の画像)のデータの性質が大きく異なると、そのままでは性能が落ちてしまう。この「ドメイン間のズレ」自体を指す言葉がドメインシフトで、これを緩和する技術がドメイン適応と呼ばれる。", "vs": "ファインチューニングはドメインシフトの問題に対する具体的な「対処法」の1つであり、ドメインシフトという「問題そのもの」を指す言葉ではない。", "opt": ["正解。ドメインシフトは学習元と学習先でデータの分布が異なるために起きる性能低下の問題を指す言葉である。", "ファインチューニングは追加学習という手法を指す言葉であり、ドメイン間のズレという問題そのものを指す言葉ではない。", "過学習は訓練データへの過剰適合を指す別の現象であり、ドメイン間のズレを指す言葉ではない。", "モード崩壊はGAN特有の生成の多様性が失われる現象を指す言葉であり、転移学習のドメインのズレとは異なるテーマの言葉である。"]}'),
  ('e-shikaku-b-q34', '4. 深層学習の応用', '自己教師あり学習の代表的な手法であるContrastive learningが学習の手がかりにしていることとして正しいものはどれか。', NULL::text, '["同じデータから作った異なる見え方(データ拡張したもの同士)は似た表現に、異なるデータ同士は似ていない表現になるように学習する。", "人間があらかじめ丁寧に付けた正解ラベルだけをひたすら頼りにし、通常の教師あり学習と全く同じやり方でそのまま淡々と学習を進めていく。", "データを一切使わず、乱数だけから意味のある表現を学習する。", "常に1種類のデータ拡張だけを使い、データ拡張を一切変化させずに学習する。"]', 0, '[0]', 'single', '{"asked": "Contrastive learningが「正解ラベルなし」でどうやって意味のある表現を学習しているか。", "why_asked": "自己教師あり学習は、ラベル付けのコストをかけずに大量データから有用な表現を学習する手法として近年重視されており、その核心的な発想を問う。", "kid": "同じ写真を少し加工したもの同士は「似ている」と教え、全く別の写真とは「似ていない」と教えることで、ラベルなしでも「似ている/似ていない」の感覚を学習させる。", "terms": [["Self-Training", "自分自身の予測結果を疑似ラベルとして使い、それをもとに学習を繰り返す自己教師あり学習の一種"], ["Co-Training", "複数の異なる視点(特徴量の組)から互いに教え合いながら学習する半教師あり学習の手法"]], "think": "Contrastive learningは、同じ画像に異なるデータ拡張(切り取り・色変化など)を施した2枚を「正例ペア」、別の画像から作ったものを「負例」として扱う。モデルは正例ペア同士の表現が近くなり、負例とは離れるように学習することで、ラベルを使わずに「画像の意味的な近さ」を捉えた表現を獲得できる。", "vs": "距離学習(Metric Learning)のSiamese networkやTriplet lossも「似ている/似ていない」を学習するという発想は共通しているが、Contrastive learningは主にラベルなしデータからの自己教師あり学習の文脈で使われる点に違いがある。", "opt": ["正解。同じデータの異なる見え方は近く、異なるデータ同士は遠くなるように表現を学習するのがContrastive learningの考え方である。", "Contrastive learningは正解ラベルを使わずに(データ拡張によって)学習の手がかりを作り出す点が、通常の教師あり学習との違いである。", "Contrastive learningは実際のデータ(とそのデータ拡張)を使って学習する手法であり、乱数だけから学習するわけではない。", "複数の異なるデータ拡張を組み合わせて多様な「見え方」を作り出すことが学習の手がかりになるため、1種類だけに固定するわけではない。"]}'),
  ('e-shikaku-b-q35', '4. 深層学習の応用', '能動学習(Active Learning)の考え方として正しいものはどれか。', NULL::text, '["ラベルなしデータの中から、モデルが最も判断に迷っている(不確実性が高い)データを選んでラベル付けを依頼することで、少ないラベル付けコストで効率よく性能を上げる。", "ラベルなしデータの中から、モデルが最も自信を持って正確に答えられる簡単で判断しやすいデータだけを、あえてわざわざ優先的に選び出してラベル付けの依頼をしてしまう。", "すべてのラベルなしデータに無作為にラベルを付け、優先順位を一切付けずに学習に使う。", "ラベル付けの作業を完全に自動化し、人間が一切関与しない仕組みで正解ラベルを生成する。"]', 0, '[0]', 'single', '{"asked": "能動学習が「どのデータに優先してラベルを付けてもらうか」をどう選んでいるか。", "why_asked": "ラベル付けのコストが高い状況で、限られた予算をどう使えば効率よく性能を上げられるかという実務的な問題意識に応える考え方。", "kid": "「これ、犬か猫かちょっと自信ないな…」というモデルが迷っているデータを優先して人間に聞き、効率よく賢くなっていく仕組み。", "terms": [["Uncertainty Sampling", "モデルの予測確率が5分5分に近いなど、不確実性が高いデータを優先して選ぶ能動学習の代表的な戦略"], ["Representative Sampling", "データ全体の分布をよく代表するようなデータを優先して選ぶ、また別の能動学習の戦略"]], "think": "すべてのデータに均等にラベルを付けるのはコストがかかりすぎる。能動学習は、モデルが既にうまく判断できているデータにはあまり価値がなく、逆に判断に迷っている(不確実性が高い)データにラベルを付けてもらう方が、モデルの改善に大きく役立つという考え方に基づいて、ラベル付けの優先順位を賢く決める。", "vs": "半教師あり学習(Self-Training等)は「モデル自身の予測を疑似ラベルとして使う」アプローチだが、能動学習は「人間に本物のラベルを付けてもらうデータを選ぶ」アプローチという違いがある。", "opt": ["正解。モデルが判断に迷っている不確実性の高いデータを優先的に選んでラベル付けを依頼するのが能動学習の基本的な考え方である。", "既に自信を持って答えられるデータにラベルを追加してもモデルの改善効果は小さく、能動学習が優先するのは不確実性の高いデータである。", "能動学習はラベル付けの優先順位を賢く決める仕組みであり、無作為に優先順位なく選ぶ方法ではない。", "能動学習は「人間にラベル付けを依頼するデータを賢く選ぶ」仕組みであり、人間の関与を完全になくす自動化そのものではない。"]}'),
  ('e-shikaku-b-q36', '4. 深層学習の応用', '距離学習(Metric Learning)で使われるTriplet lossの考え方として正しいものはどれか。', NULL::text, '["基準データ(Anchor)・同じクラスのデータ(Positive)・異なるクラスのデータ(Negative)の3つを組にし、Positiveを近づけ、Negativeを遠ざける。", "2つのデータだけを常に1組にして比較し、その2つが同じクラスかどうかにまったく関わらず、常に無条件でひたすら距離を近づけるように学習をどこまでも延々と続けて進めていくだけである。", "データを1つだけ使い、そのデータ単体の分類ラベルを直接予測するように学習する。", "すべてのデータ同士の距離を常に一定の値に固定するように学習する。"]', 0, '[0]', 'single', '{"asked": "Triplet lossが3つのデータ(Anchor・Positive・Negative)をどう使い分けているか。", "why_asked": "2サンプルによる比較(Siamese network)に対して、3サンプルによる比較(Triplet loss)がどう発展した工夫かを問う、距離学習の代表的な手法。", "kid": "「これ(基準)」「これと同じ仲間」「これとは違う仲間」の3枚を並べて、「同じ仲間とは近く、違う仲間とは遠くなるように」練習する。", "terms": [["Siamese network", "2つのデータを同じネットワークに通して、その表現の距離を比較する2サンプルによる距離学習の手法"], ["contrastive loss", "Siamese networkで使われる、2サンプルのペアが同じクラスか違うクラスかに応じて距離を近づけ/遠ざける損失"]], "think": "Triplet lossは3つ組(Anchor・Positive・Negative)を使い、「Anchorと同じクラスのPositiveとの距離」よりも「Anchorと異なるクラスのNegativeとの距離」の方が、一定のマージン以上大きくなるように学習する。これにより、同じクラス同士は表現空間で近く、異なるクラス同士は離れるような埋め込みを獲得できる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"16\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">Triplet loss：近づける/遠ざける</text><circle cx=\"170\" cy=\"70\" r=\"7\" fill=\"#3b82f6\"/><text x=\"170\" y=\"55\" fill=\"#3b82f6\" font-size=\"9\" text-anchor=\"middle\">Anchor</text><circle cx=\"220\" cy=\"85\" r=\"7\" fill=\"#6ab08d\"/><text x=\"235\" y=\"102\" fill=\"#6ab08d\" font-size=\"9\">Positive</text><circle cx=\"90\" cy=\"40\" r=\"7\" fill=\"#c47070\"/><text x=\"90\" y=\"28\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">Negative</text><line x1=\"170\" y1=\"70\" x2=\"220\" y2=\"85\" stroke=\"#6ab08d\" stroke-width=\"2\"/><text x=\"205\" y=\"70\" fill=\"#6ab08d\" font-size=\"8\">近づける</text><line x1=\"170\" y1=\"70\" x2=\"90\" y2=\"40\" stroke=\"#c47070\" stroke-width=\"1.5\" stroke-dasharray=\"3,3\"/><text x=\"115\" y=\"48\" fill=\"#c47070\" font-size=\"8\">遠ざける</text></svg>", "vs": "Siamese network(2サンプルによる比較)は「このペアは同じクラスか違うクラスか」を1回ずつ判定するのに対し、Triplet loss(3サンプルによる比較)は「近さの相対的な大小関係」まで一度に学習できる点が発展したポイント。", "opt": ["正解。Anchor・Positive・Negativeの3つを使い、Positiveとは近く、Negativeとは遠くなるように学習するのがTriplet lossである。", "Triplet lossは3つのデータを使う手法であり、2つのデータだけを常に近づける説明はTriplet lossの定義と合わない。", "Triplet lossは複数のデータ間の距離関係を学習する手法であり、1つのデータ単体のラベルを直接予測する手法ではない。", "Triplet lossはクラスの違いに応じて距離を近づけたり遠ざけたりする手法であり、すべての距離を一定に固定する手法ではない。"]}'),
  ('e-shikaku-b-q37', '4. 深層学習の応用', 'メタ学習(Meta Learning)の代表的な手法であるMAML(Model-Agnostic Meta-Learning)が目指していることとして正しいものはどれか。', NULL::text, '["複数のタスクで学習を経験させることで、新しいタスクに対しても少ないデータ・少ない更新回数ですぐに適応できるような「良い初期値」を獲得する。", "1つのタスクだけをひたすら繰り返し学習させ、そのタスクに特化した専用のモデルを作ることを目指す。", "モデルの構造(層の数やユニット数)をランダムに何度も変えながら、最も精度の高い構造をひたすら根気強く時間をかけてくまなく丹念に総当たりで探す。", "学習率やバッチサイズといったハイパーパラメータを、人手で一切調整せずに固定値のまま使い続ける。"]', 0, '[0]', 'single', '{"asked": "MAMLが「良い初期値」を通じて何を実現しようとしているか。", "why_asked": "「学習の仕方そのものを学習する」というメタ学習の発想を、通常の(1つのタスクに特化する)学習との対比で理解しているかを問う。", "kid": "色々なタスクの「練習問題」を解いてきた経験から、「新しい問題が出ても、少しの練習ですぐコツをつかめる」ような、勘の良いスタート地点を身につける。", "terms": [["メタ目的関数(meta-objective)", "個々のタスクの性能ではなく、「新しいタスクへの適応のしやすさ」自体を最適化する目的関数"], ["Model-Agnostic", "モデルの種類(CNNでもRNNでも)を問わず適用できる、という汎用性を表す言葉"]], "think": "通常の学習は1つのタスクに対してパラメータを最適化するが、MAMLは複数の異なるタスクでの学習を経験させ、「どのタスクから始めても、少数回の勾配更新で素早く適応できる」ような初期パラメータを見つけることを目指す。つまり「タスクを解く」のではなく「新しいタスクへの適応力そのもの」を学習の目的にしている。", "vs": "転移学習も「学習済みの知識を新しいタスクに活かす」という点でメタ学習と似ているが、転移学習は特定の1つの学習済みモデルを流用するのに対し、メタ学習は「複数タスクへの適応しやすさ」自体を学習の目的関数に組み込んでいる点が異なる。", "opt": ["正解。MAMLは複数タスクでの経験を通じて、新しいタスクにも少ない更新で素早く適応できる初期値を獲得することを目指す。", "MAMLは複数のタスクを経験させることで汎用的な適応力を身につける手法であり、1つのタスクだけに特化させる手法ではない。", "モデルの構造そのものを総当たりで探す手法(アーキテクチャ探索など)とは異なり、MAMLは初期パラメータの獲得を目指す手法である。", "メタ学習はむしろ「学習の仕方」自体を工夫する分野であり、ハイパーパラメータの調整を放棄する考え方ではない。"]}'),
  ('e-shikaku-b-q38', '4. 深層学習の応用', 'モデルの解釈性を高める手法であるLIME・SHAPが採用しているアプローチとして正しいものはどれか。', NULL::text, '["複雑なモデルの予測を、対象データの近傍(局所的)あるいは全体(大域的)で、人間にも理解しやすい単純なモデルで近似することで、判断の根拠を説明する。", "複雑なモデルの内部の重みを直接すべて書き換えて、単純な線形モデルそのものに置き換えてしまう。", "モデルの予測結果そのものを一切参照せず、訓練データのラベルの分布だけを見て説明を作る。", "CNNの畳み込み層の勾配情報だけを使い、画像のどこに注目したかをヒートマップとして描く手法である(これはGrad-CAMの仕組みの説明にあたる)。"]', 0, '[0]', 'single', '{"asked": "LIME・SHAPが「モデルを近似する」ことで解釈性を得ている、というアプローチの中身。", "why_asked": "Grad-CAM・Integrated Gradientsのような「勾配を直接使う」アプローチと対比して、LIME・SHAPの「モデルを近似する」という別系統のアプローチを区別できるかを問う。", "kid": "複雑な機械の動きを、その場その場だけなら「だいたいこんな単純なルールで動いてる」と簡単な言葉に言い換えて説明してくれる仕組み。", "terms": [["局所的な解釈", "1つの予測結果について、その周辺だけで成り立つ単純な説明を作るアプローチ(LIMEなど)"], ["協力ゲーム理論", "SHAPが各特徴量の貢献度を公平に配分するために使う、Shapley Valueの理論的な背景"]], "think": "LIMEは、説明したい1つのデータの近くで、少しずつ入力を変えながら複雑なモデルの予測を観察し、その狭い範囲だけで成り立つ単純な線形モデルを作ることで「なぜこの予測になったか」を説明する(局所的な解釈)。SHAPは、協力ゲーム理論のShapley Valueという考え方を使い、各特徴量が予測にどれだけ公平に貢献したかを配分することで説明する。どちらも元の複雑なモデル自体は変えず、その振る舞いを外側から近似・説明する点が共通している。", "vs": "Grad-CAM・Integrated Gradientsはモデルの内部の勾配情報を直接使って説明を作るアプローチで、LIME・SHAPの「外側からモデルを近似する」アプローチとは仕組みが異なる。", "opt": ["正解。LIME・SHAPはモデルを局所的・大域的に単純なモデルで近似することで、判断の根拠を人間に分かる形で示す。", "LIME・SHAPは元の複雑なモデルはそのまま保ちつつ外側から近似するアプローチであり、モデルの重みを直接書き換えるわけではない。", "LIME・SHAPはモデルの予測結果(の変化)を観察して説明を作る手法であり、予測結果を参照せずラベルの分布だけを見るわけではない。", "これはGrad-CAMの説明であり、LIME・SHAPは勾配情報ではなくモデルの近似によって解釈を行う点が異なる。"]}'),
  ('e-shikaku-b-q39', '5. 開発・運用環境', '連合学習(Federated learning)における「クロスデバイス学習」と「クロスサイロ学習」の違いとして正しいものはどれか。', NULL::text, '["クロスデバイス学習は多数のスマートフォンのような小さな端末を対象にするのに対し、クロスサイロ学習は病院や企業のような少数だが大きな組織単位を対象にする。", "クロスデバイス学習は病院や企業のような少数の組織のほうを対象にし、クロスサイロ学習はむしろ非常に多数のスマートフォンのような小さな端末のほうを対象にする。", "クロスデバイス学習とクロスサイロ学習はどちらも、データを1か所のサーバーに必ず集約してから学習する方式である。", "クロスデバイス学習とクロスサイロ学習は、連合学習ではなく通常のデータ並列化の別名である。"]', 0, '[0]', 'single', '{"asked": "連合学習の2つの分類(クロスデバイス・クロスサイロ)が、参加者の規模・数でどう違うか。", "why_asked": "連合学習と一言で言っても、参加者が「膨大な数の小さな端末」か「少数の大きな組織」かで、通信の安定性や参加者の信頼性などの前提が大きく変わる。", "kid": "クロスデバイスは「大勢のスマホユーザーみんなで少しずつ協力する」タイプ、クロスサイロは「少数の大きな病院や会社が協力する」タイプ。", "terms": [["Local Model", "各参加者(端末や組織)の手元で学習される、ローカルなモデル"], ["Global Model", "サーバー側で各参加者の更新を集約して作られる、全体のモデル"]], "think": "クロスデバイス学習は、非常に多数(何百万台も)のスマートフォンなどの端末が参加し、それぞれの通信環境が不安定だったり、途中で参加をやめたりすることも想定した設計が必要になる。クロスサイロ学習は、病院や企業のように参加者の数は少ないが、それぞれが比較的安定した計算資源と通信環境を持つ組織を対象にする。", "vs": "通常のデータ並列化(データセンター内の分散学習)は、高速な専用回線で結ばれた信頼できる計算資源を前提にするのに対し、連合学習(クロスデバイス・クロスサイロともに)はデータそのものを外に出さないという制約を前提にする点が根本的に異なる。", "opt": ["正解。クロスデバイスは多数の小さな端末、クロスサイロは少数の大きな組織を対象にする、規模と数の違いがある。", "対象の説明が入れ替わっている。少数の組織を対象にするのはクロスサイロ、多数の端末を対象にするのはクロスデバイスである。", "連合学習はデータを1か所に集約せずに学習することが目的であり、クロスデバイス・クロスサイロのどちらもデータを外に出さない前提で設計される。", "クロスデバイス学習・クロスサイロ学習はどちらも連合学習の分類であり、通常のデータ並列化とは前提(データが分散して存在すること)が異なる。"]}'),
  ('e-shikaku-b-q40', '5. 開発・運用環境', 'GPUの並列処理方式であるSIMD(Single Instruction Multiple Data)とSIMT(Single Instruction Multiple Thread)の違いとして正しいものはどれか。', NULL::text, '["SIMDは1つの命令で複数のデータを一斉処理する方式であるのに対し、SIMTは複数のスレッドが独立に動きつつ、同じ命令なら同期して実行する、より柔軟な方式である。", "SIMDは複数のスレッドを自由に組み合わせてかなり柔軟に使う方式であり、SIMTのほうは1つのデータだけをひたすら黙々と処理する、まったく逆の限定的な方式にあたる。", "SIMDとSIMTはどちらも、1つの命令で1つのデータだけを処理する、旧来の逐次処理の方式にすぎない。", "SIMDとSIMTは、深層学習の計算とは無関係な、画面表示専用の処理方式である。"]', 0, '[0]', 'single', '{"asked": "GPUのアーキテクチャで使われるSIMDとSIMTという、似た名前の並列処理方式の違い。", "why_asked": "「GPUがなぜ深層学習に向いているか」をSIMDのレベルよりさらに一歩踏み込んで、GPU特有のSIMTという方式まで理解しているかを問う。", "kid": "SIMDは「1つの号令でみんな全く同じ動きをする」、SIMTは「それぞれ自分のスレッドとして動きつつ、同じ命令のところではタイミングを揃える」という少し柔軟な仕組み。", "terms": [["MIMD", "複数の命令列が、それぞれ別々のデータに対して並行して処理を行う、SIMD/SIMTよりさらに柔軟な方式"], ["スレッド", "プログラムの中で並行して実行できる処理の単位。SIMTでは多数の軽量なスレッドが同時に動く"]], "think": "SIMDは1つの命令が複数のデータに全く同じ処理を強制する、比較的単純な並列方式。GPUで実際に使われるSIMTは、多数のスレッドそれぞれが個別の実行状態を持ちながらも、同じ命令を実行しているスレッド同士はハードウェア的にまとめて効率よく処理する、SIMDをスレッドの概念で発展させた方式になっている。", "vs": "MIMDはSIMD/SIMTよりもさらに柔軟で、複数の命令列がそれぞれ異なるデータに対して独立に動く方式。CPUのマルチコア処理はこのMIMDに近い。", "opt": ["正解。SIMDは1命令で複数データを一斉処理、SIMTはスレッド単位で個別性を持ちつつ同じ命令なら同期して実行する、より柔軟な方式である。", "SIMDが複数スレッドを使う方式、SIMTが1つのデータだけを処理する方式という説明は、両方とも実際の定義と逆になっている。", "SIMD・SIMTはどちらも1つの命令で「複数」のデータ(スレッド)を同時に扱う並列処理の方式であり、1つのデータだけを扱う逐次処理ではない。", "SIMD・SIMTはGPUの並列計算能力の土台であり、深層学習の行列演算などの高速化にも直接関わる方式である。"]}'),
  ('e-shikaku-b-q41', '5. 開発・運用環境', '蒸留(Distillation)で、生徒モデルに教師モデルの「ソフトターゲット(確信度の分布そのもの)」を学習させる理由として正しいものはどれか。', NULL::text, '["正解ラベル(0か1かのone-hot)だけでは伝わらない、教師モデルが持つ「クラス同士の似ている度合い」についての情報まで生徒モデルに伝えられるから。", "正解ラベルだけを使うよりも、計算にかかる時間を大幅に短縮できるから。", "ソフトターゲットを使うと、生徒モデルのパラメータ数を教師モデルより増やせるようになるから。", "ソフトターゲットを使うと、教師モデルをあらかじめ学習させておくこと自体がまるごと完全に不要になり、生徒モデルだけですべて最初から学習を完結できるから。"]', 0, '[0]', 'single', '{"asked": "蒸留で正解ラベルだけでなく、教師モデルの出力(ソフトターゲット)まで使う理由。", "why_asked": "蒸留が単なる「小さいモデルへのコピー」ではなく、教師モデルが持つ知識をどう受け渡しているかという仕組みの核心を問う。", "kid": "「これは猫です」という答えだけでなく、「猫80%、犬15%、狐5%」のように「ちょっと犬にも似てるな」という先生の感覚まで、生徒に教えてあげる、というイメージ。", "terms": [["ソフトターゲット", "教師モデルのsoftmax出力(各クラスの確信度の分布)そのものを、生徒モデルの学習目標として使うこと"], ["温度パラメータ", "softmaxの出力をより滑らかにし、クラス間の相対的な違いを見えやすくするために使う調整用のパラメータ"]], "think": "正解ラベル(one-hot)は「正解は猫」という情報しか持たないが、教師モデルのsoftmax出力(ソフトターゲット)には「猫に似ているのは犬より狐」というような、クラス間の関係性についての豊かな情報が含まれている。生徒モデルはこのソフトターゲットを真似ることで、正解ラベルだけでは学べない、より繊細な判断基準まで学習できる。", "vs": "プルーニング・量子化はモデルの構造やパラメータの表現そのものを直接いじる軽量化手法だが、蒸留は「学習のさせ方(何を目標に学習させるか)」を工夫する点で異なるアプローチ。", "opt": ["正解。ソフトターゲットにはクラス間の似ている度合いの情報が含まれ、それを生徒モデルに伝えられるのが蒸留の狙いである。", "蒸留は生徒モデルの学習目標(何を教師とするか)を工夫する手法であり、それ自体が計算時間の短縮を直接の目的とした手法ではない。", "ソフトターゲットは生徒モデルの学習の目標(教える内容)を変える工夫であり、生徒モデルのパラメータ数を増やす仕組みではない。", "蒸留はあらかじめ教師モデルを学習させておき、その出力を使って生徒モデルを学習させる手法であり、教師モデルの学習が不要になるわけではない。"]}'),
  ('e-shikaku-b-q42', '5. 開発・運用環境', '深層学習の推論をエッジ側(端末)で行うかクラウド側(サーバー)で行うかを考えるとき、それぞれの特徴として正しいものはどれか。', NULL::text, '["エッジ推論は通信の遅延やオフライン時の弱さを避けやすい代わりに端末の計算資源に制約があるのに対し、クラウド推論は豊富な計算資源を使える代わりに通信の遅延やオフライン時の弱さという課題を抱える。", "エッジ推論は常に豊富な計算資源を自由に使え、クラウド推論は常に端末側の限られた計算資源しか使えない。", "エッジ推論もクラウド推論も、通信環境やオフラインかどうかに一切影響を受けない、全く同じ特徴を持つ配置である。", "エッジ推論とクラウド推論は、モデルの精度にも速度にも消費電力にも通信環境への依存度にも一切これといった違いを生まない、実質的にはまったくもって単なる呼び方だけの違いにすぎないものにとどまってしまう。"]', 0, '[0]', 'single', '{"asked": "エッジ推論とクラウド推論、それぞれの得意・不得意なポイント。", "why_asked": "モデルの軽量化(プルーニング・蒸留・量子化)が「なぜエッジ推論の文脈で重要になるのか」という理由の裏にある、エッジとクラウドのトレードオフを整理して理解しているかを問う。", "kid": "エッジ推論は「その場ですぐ計算できる」代わりに端末の力に限りがあり、クラウド推論は「強力な計算機を使える」代わりに、通信が繋がっていないと動かせない。", "terms": [["エッジコンピューティング", "クラウドの中心的なサーバーではなく、データが発生する端末や近くの拠点側で計算を行う考え方"], ["モデルの軽量化", "エッジ推論の計算資源の制約に対応するための、プルーニング・蒸留・量子化などの工夫"]], "think": "クラウド推論はデータセンターの豊富な計算資源(GPU/TPUなど)を使えるため大きく重いモデルでも動かせるが、端末とサーバー間の通信が必要になるため、通信が遅い・不安定・オフラインといった状況に弱い。エッジ推論は端末上でその場で計算が完結するため通信に依存せず反応が速いが、端末自体の計算資源(バッテリー・メモリ・処理能力)には限りがあるため、モデルの軽量化が重要になる。", "vs": "この2つは二者択一ではなく、簡単な処理はエッジで即座に行い、より重い処理だけクラウドに任せるといった組み合わせ(ハイブリッドな配置)で使われることも多い。", "opt": ["正解。エッジ推論は通信に強いが計算資源に制約があり、クラウド推論は計算資源は豊富だが通信に依存するという、逆方向のトレードオフを持つ。", "計算資源の豊富さの説明が入れ替わっている。豊富な計算資源を使えるのはクラウド推論であり、エッジ推論は端末側の限られた資源しか使えない。", "エッジ推論とクラウド推論は通信環境への依存度が明確に異なり、全く同じ特徴を持つわけではない。", "エッジ推論とクラウド推論は速度・通信依存・消費電力などの特徴が異なる配置であり、単なる呼び方の違いではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'e-shikaku-b'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
